window.__LEX={"G4800":"<h1>suzao</h1>\n<p>Strong n° 4800 <i>Prononciation [sood-zah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>vivre ensemble avec quelqu'un\n<ol type=\"a\">\n<li>de la vie physique sur la terre</li>\n<li>vivre une nouvelle vie en union avec Christ, c.à.d. dédiée à Dieu</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συ·ζάω-ῶ</b>, <i>anc. att</i>. <b>ξυ·ζάω</b> <span>(<i>f</i>. συζήσομαι, <i>etc</i>.)</span> vivre ensemble, PLAT. <i>Pol. 302</i> b ; ARSTT. <i>Nic. 4, 6, 1, etc. ; ou</i> vivre avec : τινι, AR. <i>fr. 231 b Dind. ;</i> DÉM. <i>363, 4 ;</i> μετά τινος, DÉM. <i>330, 2 ;</i> ARSTT. <i>Nic. 8, 3, 4,</i> avec qqn ; ὕδατι, ESCHL. (<i>Bkk. 5</i>) vivre dans l’eau ; <i>fig</i>. vivre avec qqe ch. (une habitude, une passion, <i>etc.) dat</i>. DÉM. <i>13, 10 ;</i> LUC. <i>Salt. 1</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συζαω - συζάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4801":"<h1>suzeugnumi</h1>\n<p>Strong n° 4801 <i>Prononciation [sood-zyoog'-noo-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>attacher un joug à quelqu'un, mettre ensemble sous un joug</li>\n<li>joindre ensemble pour unir\n<ol type=\"a\">\n<li>du lien du mariage</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συ·ζεύγνυμι</b>, <i>anc. att</i>. <b>ξυ·ζεύγνυμι</b> <span>[ῡ]</span> <span>(<i>f</i>. -ζεύξω, <i>ao</i>. συνέζευξα, <i>pf. inus. ; pass. ao.2</i> συνεζύγην <span>[ζῠ]</span>, <i>pf</i>. συνέζευγμαι)</span><br><b>      1</b> mettre ensemble sous le joug, atteler ensemble, HDT. <i>4, 189 ; au pass</i>. être accouplé, être apparié, XÉN. <i>Cyr. 2, 2, 26 ;</i> ARSTT. <i>H.A. 7, 6, 1, etc. ; fig</i>. être attelé, <i>càd</i>. être lié (à un sort, à une destinée, <i>etc.) dat</i>. EUR. <i>Alc. 482, Hel. 255, Hipp. 1389, etc. ;</i><br><b>      2</b> <i>fig</i>. unir par mariage, EUR. <i>Alc. 166 ;</i> XÉN. <i>Œc. 7, 30 ;</i><br><b>      3</b> <i>p. ext</i>. unir étroitement, <i>au pass</i>. être intimement uni, XÉN. <i>Lac. 2, 12 ; en parl. de choses,</i> PLAT. <i>Rsp. 546</i> c ; ARSTT. <i>Nic. 10, 8, 3, etc. ;</i><br><b><i>Moy.</i></b> atteler pour soi, <i>acc</i>. XÉN. <i>Cyr. 6, 1, 51</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συζευγνυμι - συζεύγνυμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4802":"<h1>suzeteo</h1>\n<p>Strong n° 4802 <i>Prononciation [sood-zay-teh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>chercher ou examiner ensemble</li>\n<li>dans le N.T. discuter, disputer, se demander, s'interroger</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συ·ζητέω-ῶ :<br>      1</b> faire des recherches avec : τινι, PLAT. <i>Crat. 384</i> c, avec qqn ; τινι περί τινος, PLAT. <i>Men. 90</i> b, avec qqn sur qqe ch. ;<br><b>      2</b> discuter avec : τινι, NT. <i>Ap. 6, 9 ; ou</i> πρός τινα, NT. <i>Ap. 9, 29 ; Marc. 1, 27,</i> avec qqn.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συζητεω - συζητέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (6)</li>\n<li>Luc (2)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4803":"<h1>suzetesis</h1>\n<p>Strong n° 4803 <i>Prononciation [sood-zay'-tay-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>questions réciproques et mutuelles, dispute, discussion vive</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συζήτησις, εως (ἡ) :<br>      1</b> recherche en commun, CIC. <i>Fam. 16, 21, 4 ;</i><br><b>      2</b> discussion, NT. <i>Ap. 15, 7 ; 28, 29</i>.<br><span><b>Étym</b>. συζητέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συζητησις - συζήτησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G4804":"<h1>suzetetes</h1>\n<p>Strong n° 4804 <i>Prononciation [sood-zay-tay-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un disputeur, c.à.d. un qui discute avec instruction, un sophiste un polémiste, un raisonneur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συζητητής, οῦ (ὁ)</b> qui se livre à des recherches <i>ou</i> à des discussions, NT. <i>1Cor. 1, 20</i>.<br><span><b>Étym</b>. συζητέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συζητητης - συζητητής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4805":"<h1>suzugos</h1>\n<p>Strong n° 4805 <i>Prononciation [sood'-zoo-gos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ensemble sous le joug, compagnon de peine, collègue\n<ol type=\"a\">\n<li>de ceux unis par le lien du mariage, les relations, la fonction, le travail, les études, les affaires ...</li>\n<li>d'un compagnon de joug, copain, compagnon, camarade, collègue, associé, partenaire</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σύ·ζυγος, ος, ον</b> <span>[ζῠ]</span> uni sous le même joug, <i>d’où :</i><br><b>   I</b> uni, accouplé, <i>particul. :</i><br><b>      1</b> uni par mariage, ESCHL. <i>Ch. 599 ;</i> ζῷα σ. ARSTT. <i>H.A. 9, 2, 2,</i> animaux qui vivent par couples ; <i>subst</i>. ἡ σ. épouse, EUR. <i>Alc. 314, 342 ;</i><br><b>      2</b> uni par les liens du sang, <i>d’où subst</i>. ὁ σ. frère, EUR. <i>Tr. 1001 ;</i><br><b>      3</b> uni par les liens de l’amitié, <i>d’où subst</i>. ὁ σ. compagnon, EUR. <i>I.T. 250 ;</i> AR. <i>Pl. 945 ;</i><br><b>   II</b> <i>p. ext</i>. apparenté, analogue, semblable, <i>en parl. de choses,</i> PLUT. <i>M. 10</i> d ; <i>particul. en parl. de formes grammaticales c</i>. ἐμεῦς, τεῦς, ἡμέων, ὑμέων, DYSC. <i>Pron. 307, 316, etc</i>.<br><span><b>Étym</b>. σ. ζυγός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συζυγος - σύζυγος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4806":"<h1>suzoopoieo</h1>\n<p>Strong n° 4806 <i>Prononciation [sood-zo-op-oy-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire que des gens vivent ensemble\n<ol type=\"a\">\n<li>des Chrétiens, avec Christ</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συ·ζωοποιέω-ῶ</b>, rendre vivant <i>ou</i> vivifier ensemble, NT. <i>Eph. 2, 5</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συζωοποιεω - συζωοποιέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4807":"<h1>sukaminos</h1>\n<p>Strong n° 4807 <i>Prononciation [soo-kam'-ee-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sycomore, arbre ayant la forme et le feuillage du mûrier, mais avec un fruit ressemblant à la figue</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συκάμινος, ου</b> (ἡ <i>ou</i> ὁ) <span>[ῡᾰῑ]</span> mûrier, AMPHIS (<i>Com. fr. 3, 318</i>) ; TH. <i>C.P. 6, 6, 4, etc</i>.<br><span><b><span class=\"arrow\"></span></b> ἡ σ. TH. <i>l. c. ;</i> ὁ σ. AMPHIS <i>l. c</i>.<br><span><b>Étym</b>. συκῆ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συκαμινος - συκάμινος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4808":"<h1>suke</h1>\n<p>Strong n° 4808 <i>Prononciation [soo-kay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un figuier, arbre à figues</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συκῆ</b>, <i>v</i>. συκέα <i>et</i> συκέη.<br><br>\n<b>συκέα, ας</b>, <i>par contr</i>. <b>συκῆ, ῆς (ἡ)</b> <span>[ῡ]</span><br><b>   I</b> <i>arbre et fruit :</i><br><b>      1</b> figuier, OD. <i>7, 116, etc. ;</i> HDT. <i>1, 193 ; 4, 23 ;</i> XÉN. <i>Œc. 19, 12 ;</i> PLAT. <i>Hipp. ma. 291</i> c, <i>etc. ;</i><br><b>      2</b> figue, AR. <i>Av. 490 ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> résine du pin, TH. <i>H.P. 3, 9, 3 ;</i><br><b>      2</b> <i>autre n. du</i> πέπλος <i>ou</i> πεπλίς, DIOSC. <i>4, 264 ;</i><br><b>      3</b> fic, <i>sorte d’ulcère,</i> DIOSC. <i>1, 200 ; particul</i>. tumeur au talon d’un cheval, APSYRT. (GEOP.).<br><span><b><span class=\"arrow\"></span></b> <i>Ion. et épq</i>. συκέη, HDT. <i>l. c., etc. ; nom. pl</i>. συκέαι, <i>dissyll</i>. OD. <i>7, 116 ; gén</i>. συκέων <i>ou</i> συκεέων, HDT. <i>1, 193 ; acc. pl</i>. συκέας, <i>dissyll</i>. OD. <i>24, 341 ; contracté en συκῆ, dans Hom</i>. OD. <i>7, 116 ; 11, 590 ; 24, 246. Dans les inscr. att. contracté en</i> συκῆ, CIA. <i>2, 577, a, 10 (4<sup>e</sup> siècle av. J.C.) ; v. Meisterh. p. 97, 20</i>.<br><span><b>Étym</b>. σῦκον, <i>cf. lat</i>. fīcus.</span><br><br>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συκη - συκῆ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 15 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (4)</li>\n<li>Luc (3)</li>\n<li>Jean (2)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4809":"<h1>sukomoraia</h1>\n<p>Strong n° 4809 <i>Prononciation [soo-kom-o-rah'-yah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un sycomore</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συκομορέα</b>, <i>c</i>. συκομοραία.<br><br>\n<b>συκομοραία</b> <i>ou</i> <b>συκομορέα, ας (ἡ)</b> <span>[ῡ]</span> <i>c</i>. συκόμορος, NT. <i>Luc. 19, 4</i>.<br><br>\n<b>συκό·μορος, ου (ἡ)</b> <span>[ῡ]</span> sycomore <i>ou</i> figuier d’Égypte, DIOSC. <i>1, 181</i>.<br><span><b>Étym</b>. σῦκον, μόρον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συκομοραια - συκομορέα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4810":"<h1>sukon</h1>\n<p>Strong n° 4810 <i>Prononciation [soo'-kon]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une figue, le fruit mûr d'un figuier</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σῦκον, ου (τὸ) :<br>   I</b> figue, OD. <i>7, 121 ;</i> HDT. <i>2, 40 ;</i> AR. <i>Vesp. 303, etc. ;</i> PLAT. <i>Leg. 845</i> b, <i>etc. ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> petite excroissance aux paupières, AR. <i>Ran. 1247 ;</i> HPC. <i>Epid. 3, 1085 ; ou</i> à l’anus, MÉD. ;<br><b>      2</b> parties de la femme, AR. <i>Pax 1349 ;</i> A. PL. <i>240, 8</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Béot</i>. τῦκον, STRATT. (<i>Com. fr. 2, 781</i>).</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συκον - σῦκον</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4811":"<h1>sukophanteo</h1>\n<p>Strong n° 4811 <i>Prononciation [soo-kof-an-teh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>accuser à tort, calomnier, attaquer avec des desseins méchants</li>\n<li>extorquer de l'argent\n<ol type=\"a\">\n<li>frauder</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συκοφαντέω-ῶ</b> <span>[ῡ]</span><br><b>   I <i>intr. :</i><br>      1</b> faire métier de calomniateur, AR. <i>Av. 1452 ;</i> PLAT. <i>Rsp. 431</i> c, <i>etc. ;</i><br><b>      2</b> donner des conseils perfides, être fourbe, DÉM. <i>475, 26 ;</i><br><b>   II <i>tr. :</i><br>      1</b> calomnier, accuser faussement : τινα, AR. <i>Ach. 519, Vesp. 1096, etc. ;</i> XÉN. <i>Mem. 2, 9, 5 ;</i> DÉM. <i>273, 22 ;</i> ARSTT. <i>Pol. 5, 4, 1 ;</i> PLUT. <i>M. 537</i> f, <i>etc</i>. qqn ; <i>au pass</i>. être faussement accusé, LYS. <i>152, 36, etc. ;</i><br><b>      2</b> imaginer calomnieusement : τι, DÉM. <i>639, 17,</i> qqe ch., <i>càd</i>. imaginer qqe calomnie <i>ou</i> qqe mauvaise chicane ;<br><b>      3</b> extorquer par des calomnies <i>ou</i> des chicanes, <i>acc</i>. LYS. <i>177, 32 ;</i><br><b>      4</b> imaginer une fraude, une machination perfide : τί τινος, NT. <i>Luc. 19, 8,</i> qqe machination contre qqn.<br><span><b>Étym</b>. συκοφάντης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συκοφαντεω - συκοφαντέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G4812":"<h1>sulagogeo</h1>\n<p>Strong n°4812 <i>Prononciation [soo-lag-ogue-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>emporter du butin\n<ol type=\"a\">\n<li>emmener quelqu'un comme captif (et esclave)</li>\n<li>conduire hors de la vérité et assujettir à sa domination</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συλ·αγωγέω-ῶ</b> <span>[ῡᾰ]</span><br><b>      1</b> emporter comme butin, enlever, <i>acc</i>. HLD. <i>10, 35 ; fig</i>. NT. <i>Col. 2, 8 ;</i><br><b>      2</b> piller, dévaster, <i>acc</i>. ARISTÉN. <i>2, 22</i>.<br><span><b>Étym</b>. σῦλον, ἀγωγός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συλαγωγεω - συλαγωγέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4813":"<h1>sulao</h1>\n<p>Strong n° 4813 <i>Prononciation [soo-lah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>voler, dérober, dépouiller</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συλάω-ῶ</b> <span>[ῡ]</span> <span>(<i>impf</i>. ἐσύλων, <i>f</i>. συλήσω, <i>ao</i>. ἐσύλησα, <i>pf</i>. σεσύληκα, <i>pl.q.pf</i>. ἐσεσυλήκειν ; <i>pass. f</i>. συληθήσομαι, <i>ao</i>. ἐσυλήθην, <i>pf</i>. σεσύλημαι, <i>pl.q.pf</i>. ἐσεσυλήμην)</span><br><b>      1</b> ôter, tirer de : τόξον, IL. <i>4, 105,</i> tirer un arc de sa case ; πῶμα φαρέτρης, IL. <i>4, 116,</i> ôter le couvercle d’un carquois ;<br><b>      2</b> <i>particul</i>. ôter les armes d’un ennemi vaincu, le dépouiller de ses armes, <i>avec l’acc. de la pers. qu’on dépouille,</i> IL. <i>4, 466 ; 6, 28 ; 10, 343, 387 ; 13, 640 ; avec double acc. :</i> τινά τι, IL. <i>6, 71 ; 15, 428 ; 16, 500,</i> dépouiller qqn de ses armes ; <i>p. suite,</i> dépouiller, <i>en gén., avec l’acc. de la pers. ou de la chose qu’on dépouille :</i> τινα, PLAT. <i>Rsp. 469</i> d, <i>etc</i>. dépouiller qqn ; τι, HDT. <i>6, 101 ;</i> ESCHL. <i>Pers. 810, etc</i>. dépouiller <i>ou</i> piller qqe ch. (un temple, une statue de dieu, <i>etc.) ; au pass</i>. être dépouillé, EUR. <i>Hel. 600 ; avec l’acc. de l’objet qu’on enlève (armes, etc</i>.) ESCHL. <i>Pr. 761 ;</i> SOPH. <i>Ph. 413, etc. ; avec double rég. :</i> τινά τι, HDT. <i>5, 36 ;</i> DÉM. <i>616, 19 ; ou</i> τινά τινος, EUR. <i>Hel. 669,</i> dépouiller qqn de qqe ch. ; <i>fig</i>. DÉM. <i>442, 7</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. impf. 3 sg. épq</i>. σύλα <span>[ᾱ]</span> IL. <i>4, 116. Impf. itér. 3 sg</i>. σύλασκε, HÉS. <i>Sc. 480. Ao. part. dor</i>. συλάσαις <span>[ᾱ]</span> PD. <i>P. 12, 16. Pass. ao. part. dor</i>. συλαθείς <span>[ᾱ]</span> PD. <i>O. 9, 89 ;</i> EUR. <i>Ion 917. Moy. fut. au sens pass</i>. συλήσομαι, PAUS. <i>4, 7, 4</i>.<br><span><b>Étym</b>. σύλη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συλαω - συλάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4814":"<h1>sullaleo</h1>\n<p>Strong n° 4814 <i>Prononciation [sool-lal-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>parler avec</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συλ·λαλέω-ῶ</b> <span>[ᾰ]</span> parler ensemble <i>ou</i> avec : τινι, POL. <i>4, 22, 8 ;</i> πρός τινα, NT. <i>Luc. 4, 36 ;</i> μετά τινος, NT. <i>Matth. 17, 3, etc</i>. avec qqn.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συλλαλεω - συλλαλέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (3)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4815":"<h1>sullambano</h1>\n<p>Strong n° 4815 <i>Prononciation [sool-lam-ban'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>saisir, arrêter, capturer, prendre : quelqu'un comme prisonnier</li>\n<li>concevoir, d'une femme\n<ol type=\"a\">\n<li>métaph. de luxure que l'homme favorise sous impulsion</li>\n</ol>\n</li>\n<li>se saisir\n<ol type=\"a\">\n<li>dans un sens hostile, faire quelqu'un prisonnier</li>\n</ol>\n</li>\n<li>se tenir lié avec quelqu'un, donner assistance, aider, secourir, collaborer, venir en aide</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συλ·λαμϐάνω</b> <span>(<i>f</i>. συλλήψομαι, <i>ao.2</i> συνέλαϐον, <i>pf</i>. συνείληφα, <i>etc</i>.)</span><br><b>      1</b> prendre ensemble, <i>càd. :</i> rassembler, réunir : σ. τῆς στρατιῆς τοὺς περιγενομένους, HDT. <i>5, 46,</i> rassembler les débris de l’armée ; τὸ ἕτερον στράτευμα, XÉN. <i>Cyr. 3, 3, 1,</i> rassembler le reste de l’armée ; ἁπάσας τὰς δυνάμεις, PLAT. <i>Gorg. 456</i> a, embrasser, renfermer toutes les autres forces ; <i>particul</i>. embrasser dans le discours : σ. πᾶν, HDT. <i>7, 16 ;</i> ἑνὶ ἔπεϊ πάντα σ. HDT. <i>3, 82,</i> résumer tout d’un mot ; <i>cf</i>. EUR. <i>I.T. 528 ;</i> PLAT. <i>Men. 76</i> a ; εἰς ἓν πάντα σ. PLAT. <i>Soph. 234</i> b ; τὰ ἄλλα εἰς ταὐτό, PLAT. <i>Pol. 263</i> d, rassembler tout <i>ou</i> le reste en une masse, en un groupe ;<br><b>      2</b> comprimer, réunir <i>ou</i> fermer en étreignant, étreindre : τὸ στόμα καὶ τοὺς ὀφθαλμούς, PLAT. <i>Phæd. 118</i> c, fermer la bouche et les yeux à un mort ; σ. αὐτοῦ τὸ στόμα, AR. <i>Ach. 926,</i> lui tenir la bouche fermée ;<br><b>      3</b> prendre avec soi, emporter, emmener : τινά, SOPH. <i>Tr. 1153 ;</i> EUR. <i>Ion 1217 ;</i> AR. <i>Vesp. 122, etc</i>. qqn ; σ. ἑαυτὸν ἐκ γῆς, SOPH. <i>Ph. 577,</i> partir à la hâte du pays ; <i>avec idée de violence,</i> HDT. <i>6, 26 ;</i> κόμην σ. χερί, SOPH. <i>Aj. 310,</i> s’arracher les cheveux ; <i>avec le gén. :</i> σ. τέττιγα τοῦ πτεροῦ, LUC. <i>Pseud. 1,</i> tenir, saisir une cigale par l’aile ; σ. τῶν σχοινίων, AR. <i>fr. 437,</i> retenir par la corde ; <i>particul</i>. σ. τινά, HDT. <i>1, 80, etc. ;</i> SOPH. <i>Ph. 979, 1003, etc</i>. saisir, arrêter qqn ; <i>au pass</i>. THC. <i>1, 20, etc. ;</i> σ. τινὰ ζῶντα, EUR. <i>Rhes. 513,</i> se saisir de qqn vivant ; τινὰ ὅμηρον, EUR. <i>Or. 1189,</i> retenir qqn en otage ; τινὰ ἐπὶ θανάτῳ, ISOCR. <i>73</i> a, arrêter qqn pour le conduire à la mort ; <i>cf</i>. LUC. <i>D. mort. 12, 3, etc. ;</i><br><b>      4</b> <i>fig</i>. embrasser par la pensée, comprendre : τὸν λόγον, HDT. <i>2, 49,</i> le discours ; τὴν Ἑλλάδα γλῶσσαν, HDT. <i>2, 56,</i> savoir la langue grecque ; <i>cf</i>. PLAT. <i>Pol. 278</i> c, <i>Lach. 194</i> b ; <i>avec un relat. :</i> σ. τὸ φῦλον τί ποτ' ἐστίν, PLAT. <i>Soph. 218</i> c, comprendre ce qu’est la race, la tribu ;<br><b>      5</b> concevoir, devenir enceinte, <i>en parl. de pers. et d’animaux, abs</i>. ARSTT. <i>H.A. 7, 1 ; G.A. 1, 19, etc. ; avec l’acc</i>. LUC. <i>V.H. 1, 22 ; en parl. de la matrice,</i> ARSTT. <i>H.A. 7, 4, 1, etc. ;</i><br><b>      6</b> prendre avec qqn, <i>càd</i>. mettre la main avec qqn, <i>d’où</i> aider, assister, secourir : <i>abs</i>. ESCHL. <i>Ch. 812 ;</i> SOPH. <i>Tr. 1019 ;</i> THC. <i>1, 118, etc. ;</i> σ. τινί, HDT. <i>6, 125 ;</i> SOPH. <i>fr. 666 Dind. ;</i> EUR. <i>Med. 812, etc. ;</i> PLAT. <i>Leg. 905</i> c, <i>etc</i>. venir en aide à qqn ; σ. τὰ δυνατὰ τῇ πόλει, AR. <i>Eccl. 861,</i> aider l’État selon ses forces, dans la mesure de ses forces ; σ. τὸ δέον, XÉN. <i>Cyr. 3, 1, 28,</i> aider dans ce qui est nécessaire ; σ. τινί τι, HDT. <i>7, 6 ;</i> XÉN. <i>Cyr. 7, 5, 49, etc. ; ou</i> τινί τινος, XÉN. <i>Hipp. 1, 22 ;</i> EUR. <i>Med. 946, etc</i>. assister qqn en qqe ch. ; τινὶ εἴς τι, XÉN. <i>Mem. 2, 6, 28,</i> aider qqn pour qqe ch. ; εἴς τι, XÉN. <i>Cyr. 1, 6, 25,</i> aider à qqe ch., contribuer à qqe ch. ; <i>avec un double dat. de pers. et d’instrum</i>. σ. τινὶ οὔτε χρήμασιν οὔτε σώμασι, DÉM. <i>231, 25,</i> ne secourir qqn ni de son argent, ni de ses troupes ;<br><b><i>Moy.</i></b> :<br><b>      1</b> mettre la main à… avec…, saisir avec, aider à, prendre une part de qqe ch. <i>gén</i>. AR. <i>Lys. 313 ;</i><br><b>      2</b> aider, assister, <i>abs</i>. PLAT. <i>Leg. 709</i> c ; συλλαϐέσθαι τινός (τινι) EUR. <i>Med. 946 ;</i> PLAT. <i>Theag. 129</i> e, <i>etc</i>. aider qqn en qqe ch., l’assister en qqe ch. ; σ. νόσου κάμνοντι, SOPH. <i>Ph. 282,</i> soulager un homme qui souffre (<i>litt</i>. prendre avec celui qui souffre une part de son mal) ; ξυνελάϐοντο τοῦ τοιούτου οὐχ ἥκιστα, ὥστε, <i>etc</i>. THC. <i>4, 47,</i> ils ne contribuèrent pas peu à cela que, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. moy</i>. PHILÉM. (STOB. <i>Ecl. eth. 2, p. 338</i>).</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συλλαμβανω - συλλαμβάνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 16 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (7)</li>\n<li>Jean (1)</li>\n<li>Actes (4)</li>\n<li>Philippiens (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4816":"<h1>sullego</h1>\n<p>Strong n° 4816 <i>Prononciation [sool-leg'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>recueillir, rassembler, ramasser, récolter</li>\n<li>collecter avec le but d'emporter</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συλ·λέγω</b> <span>(<i>impf</i>. συνέλεγον, <i>f</i>. συλλέξω, <i>ao</i>. συνέλεξα, <i>pf</i>. συνείλοχα ; <i>pass. f</i>. συλλεγήσομαι, <i>ao</i>. συνελέχθην, <i>ao.2</i> συνελέγην, <i>pf</i>. συνείλεγμαι <i>et</i> συλλέλεγμαι, <i>pl.q.pf</i>. συνειλέγμην)</span><br><b>   I</b> rassembler, ramasser, réunir :<br><b>      1</b> <i>au propre :</i> κτέατα, IL. <i>18, 301,</i> rassembler des troupeaux ; ὀστέα, HDT. <i>1, 68,</i> des ossements ; ξύλα, SOPH. <i>fr. 218 Dind</i>. ramasser des morceaux de bois ; ἐράνους, DÉM. <i>574, 12,</i> recueillir des cotisations ; <i>abs. en mauv. part,</i> ramasser des informations de tous côtés, DÉM. <i>525, 23 ;</i> τὴν ἐκκλησίαν, XÉN. <i>Hell. 3, 3, 8,</i> réunir l’assemblée ; <i>d’où au pass. (particul. à l’ao.2</i>) se rassembler, HDT. <i>1, 87 ; 7, 8, etc</i>. AND. <i>17, 25 ; en mauv. part,</i> ramasser, compiler, <i>acc</i>. AR. <i>Ran. 849, 1297, etc. ;</i> DÉM. <i>328, 11 ; 522, 12 ;</i><br><b>      2</b> <i>fig</i>. σ. σθένος, EUR. <i>Ph. 850,</i> rassembler ses forces ; σ. ἑαυτόν, PLAT. <i>Ax. 370</i> e, <i>m. sign. ;</i><br><b>   II</b> former par la réunion de plusieurs choses : στρατόν, THC. <i>4, 77 ;</i> στράτευμα, XÉN. <i>An. 6, 1, 6,</i> assembler une armée ; <i>p. suite, au pass. :</i><br><b>      1</b> être le produit de, le résultat de, résulter : ἐκ τούτων συνελέγετο αὐτῷ ἡ πολυλογία, XÉN. <i>Cyr. 1, 4, 3,</i> de tout cela résultait chez lui l’habitude de parler beaucoup ;<br><b>      2</b> aboutir : εἰς ταὐτό τινι, PLAT. <i>Leg. 961</i> a, à la même conclusion que qqn ;<br><b><i>Moy.</i></b> <span>(<i>f</i>. συλλέξομαι, <i>ao</i>. συνελεξάμην, <i>pf</i>. συνείλεγμαι)</span><br><b>      1</b> rassembler qqe ch. à soi, <i>acc</i>. IL. <i>18, 413 ;</i><br><b>      2</b> rassembler pour soi (des armes, des compagnons, <i>etc.) acc</i>. OD. <i>2, 292 ;</i> XÉN. <i>An. 7, 4, 8</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. pf</i>. συνείλοχα (<i>var</i>. συνείλεχα) DÉM. <i>328, 11 ; 522, 12. Pass. fut. 3</i> συλλεγήσομαι, ESCHN. <i>68, 1 ; ao.1</i> συνελέχθην, HDT. <i>1, 97 ;</i> PLAT. <i>Leg. 784</i> a ; <i>d’ord</i>. συνελέγην, HDT. <i>7, 173 ; 9, 27 ;</i> AR. <i>Vesp. 1107, etc. ; pf</i>. συνείλεγμαι <i>au sens pass</i>. THC. <i>3, 94, etc. ; au sens moy</i>. XÉN. <i>Mem. 4, 2, 1 ;</i> DÉM. <i>1351, 10 ; ou</i> συλλέλεγμαι, HDT. <i>7, 26 ; 9, 41 ;</i> AR. <i>Eccl. 58. Moy. ao. 3 sg. épq</i>. ξυλλέξατο (<i>var</i>. συλλέξατο) IL. <i>18, 413. Forme ion. et att. en</i> ξυν-, HDT. <i>2, 94 ;</i> THC. <i>3, 94, etc. ;</i> AR. <i>Ach. 184 ;</i> ARR. <i>An. 3, 19, 2</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συλλεγω - συλλέγω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4817":"<h1>sullogizomai</h1>\n<p>Strong n° 4817 <i>Prononciation [sool-log-id'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>apporter ensemble des comptes, compter, calculer, supputer</li>\n<li>compter pour soi-même, raisonner</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συλλογίζω</b>, assembler, rassembler, DH. <i>Vet. script. cens. 1 fin ;</i><br><b><i>Moy.</i></b> <span>(<i>f</i>. συλλογίσομαι, <i>ao</i>. συνελογισάμην, <i>rar</i>. συνελογίσθην, <i>pf</i>. συλλελόγισμαι)</span> assembler par la pensée, <i>d’où :</i><br><b>      1</b> faire le compte de, <i>acc</i>. HDT. <i>2, 148 ;</i> LYS. <i>906, 10 ;</i> PLAT. <i>Leg. 799</i> a, <i>etc. ;</i><br><b>      2</b> <i>p. suite,</i> récapituler, <i>acc</i>. DÉM. <i>396, 28, etc. ; ou</i> résumer, ARSTT. <i>Metaph. 7, 1, 1, etc. ;</i><br><b>      3</b> se rendre compte de, <i>acc</i>. PLUT. <i>Pomp. 60 ; avec</i> ὅτι, PLAT. <i>Leg. 670</i> c ;<br><b>      4</b> faire un raisonnement, <i>particul</i>. conclure de prémisses, <i>acc</i>. PLAT. <i>Gorg. 479</i> c, <i>etc. ; au pass</i>. être déduit selon un raisonnement régulier, ARSTT. <i>An. pr. 1, 25 ; p. opp. à</i> ἀσυλλόγιστα, ARSTT. <i>Rhet. 1, 2, 18, etc. ; particul</i>. faire un raisonnement par voie de syllogisme, ARSTT. <i>An. pr. 1, 23, 3, etc. ; d’où</i> conclure, décider de, <i>avec l’inf</i>. POL. <i>14, 4, 4 ;</i><br><b>      5</b> calculer, supposer, conjecturer : τι ἔκ τινος, ARSTT. <i>Rhet. 1, 2, 13 ;</i> POL. <i>9, 30, 8,</i> une ch. d’après une autre.<br><span><b>Étym</b>. σύλλογος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συλλογιζομαι - συλλογίζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4818":"<h1>sullupeo</h1>\n<p>Strong n° 4818 <i>Prononciation [sool-loop-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être affecté par le chagrin d'un autre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συλ·λυπέω-ῶ</b> <span>[λῡ]</span> affliger ensemble <i>ou</i> avec, <i>dat</i>. ARSTT. <i>Nic. 9, 11, 4 ; au pass</i>. s’affliger avec, compatir à : τινι, HDT. <i>6, 39 ; 9, 94 ;</i> PLAT. <i>Rsp. 462</i> e ; ἐπί τινι, NT. à qqe douleur.<br><span><b><span class=\"arrow\"></span></b> <i>Part. prés. pass. ion</i>. συλλυπεύμενοι, HDT. <i>9, 24 ; fut. pass</i>. συλλυπηθήσομαι, HDT. <i>6, 39 ; fut. moy</i>. συλλυπήσομαι, PLAT. <i>l. c</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συλλυπεω - συλλυπέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4819":"<h1>sumbaino</h1>\n<p>Strong n° 4819 <i>Prononciation [soom-bah'-ee-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>marcher à petits pas (les pieds rapprochés)</li>\n<li>venir ensemble, rencontrer quelqu'un</li>\n<li>de choses qui arrivent au même moment, qui se passent</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·ϐαίνω</b> <span>(<i>impf</i>. συνέϐαινον, <i>f</i>. συμϐήσομαι, <i>ao.2</i> συνέϐην, <i>pf</i>. συμϐέϐηκα, <i>pass. ao</i>. συνεϐάθην, <i>pf</i>. συμϐέϐασμαι, <i>v. ci-dessous</i>)</span><br><b>   I</b> marcher ensemble, <i>càd. :</i><br><b>      1</b> se tenir de façon que les pieds soient réunis, se tenir debout les pieds joints, <i>p. opp. à</i> διαϐαίνειν, XÉN. <i>Eq. 1, 14 ;</i> συμϐᾶσα τὼ πόδε, A. TAT. <i>1, 1,</i> ayant les deux pieds rapprochés, <i>en parl. d’une femme à cheval, p. opp. à</i> περιϐάδην ;<br><b>      2</b> se réunir, se rassembler avec, <i>dat</i>. XÉN. <i>Hell. 1, 2, 17 ;</i> ἡ Κύπρις μοι συμϐέϐηκεν οὐδαμοῦ, EUR. <i>Hel. 1007,</i> Kypris ne s’est jamais approchée de moi, n’a rien eu à faire avec moi ; συμϐῆναι ποδί, SOPH. <i>Aj. 1281,</i> combattre de pied ferme ;<br><b>      3</b> <i>fig</i>. s’ajouter à, se joindre à : κακοῖς, EUR. <i>Hel. 37,</i> à des souffrances, les augmenter ;<br><b>   II</b> <i>fig</i>. tomber d’accord : λόγοις συμϐῆναι, s’engager par des paroles. EUR. <i>Med. 735 ; ou</i> se déclarer d’accord avec les paroles de qqn, EUR. <i>Andr. 233 ; particul. :</i><br><b>      1</b> se réconcilier, AR. <i>Vesp. 867 ;</i> σ. ἐς τὠϋτό, HDT. <i>1, 13,</i> tomber d’accord ; σ. καθ' ὁμολογίαν, THC. <i>1, 98, m. sign. ; avec le dat. de la pers. avec laquelle on s’entend ou se réconcilie,</i> THC. <i>3, 52 ; 4, 128 ; 5, 80, etc. ;</i> ἐὰν ξυμϐῶ τί σοι, AR. <i>Ran. 175,</i> si je m’entends avec toi en quelque façon (sur le salaire) ; σ. πρός τινα, THC. <i>1, 103 ; 3, 27,</i> s’entendre avec qqn, conclure un arrangement avec qqn ; <i>avec l’acc. neutre de la chose sur laquelle on tombe d’accord :</i> σ. τι, THC. <i>2, 5 ; 4, 22, etc</i>. tomber d’accord sur qqe ch. ; οὐδὲν σ. THC. <i>5, 36,</i> ne tomber d’accord sur rien ; <i>au pass</i>. ἕως ἄν τι περὶ τοῦ πλέονος ξυμϐαθῇ, THC. <i>4, 30,</i> jusqu’à ce qu’une entente fût conclue sur l’affaire définitive (le point le plus important) ; <i>avec un inf. accompagné d’un acc. ou d’un nom :</i> ξυνέϐησαν, ἤν τις ἁλίσκηται, τοῦ λαϐόντος εἶναι δοῦλον, THC. <i>1, 103,</i> ils convinrent que si qqn était pris, il serait esclave de celui qui l’aurait pris ; <i>de même avec le nom</i>. THC. <i>1, 117 ; cf</i>. THC. <i>2, 4, etc. ;</i> XÉN. <i>Hell. 6, 2, 36 ; avec l’inf</i>. THC. <i>4, 54 ; avec</i> ὥστε <i>et l’inf</i>. HDT. <i>1, 82 ;</i> THC. <i>4, 46 ;</i><br><b>      2</b> s’unir à, sympathiser avec, s’accorder avec, <i>dat</i>. AR. <i>Ran. 807 ;</i> DH. <i>2, 62 ;</i><br><b>      3</b> <i>en parl. d’objets inanimés,</i> s’adapter l’un à l’autre, <i>en parl. de pierres,</i> M. ANT. <i>5, 8 ; de talons qui s’adaptent à des traces de pas,</i> ESCHL. <i>Ch. 210 ; d’où, en parl. du temps,</i> se rencontrer, tomber juste, coïncider, HDT. <i>1, 116 ;</i> αὐτὸ συμϐαίνει εἰς ταύτην εἶναι πέμπτην, DÉM. <i>360, 5,</i> il se trouve précisément que c’est jusque-là le 5<sup>e</sup> jour ;<br><b>      4</b> s’accorder avec, répondre à, s’harmoniser avec, cadrer, être d’accord avec, <i>dat</i>. HDT. <i>2, 3 ;</i> LYS. <i>113, 10 ;</i> τὸ περὶ σὲ ἄριστον τῷ παντὶ ξυμϐαίνει, PLAT. <i>Leg. 903</i> d, ton intérêt s’accorde avec le tout (avec l’intérêt du tout) ; <i>abs</i>. s’accorder, être en harmonie, EUR. <i>Hel. 622 ;</i> AR. <i>Eq. 220 ;</i><br><b>      5</b> <i>en parl. de sommes d’argent,</i> faire ensemble, s’élever à, XÉN. <i>Hell. 6, 4, 12 ;</i> ARSTD. <i>t. 1, 343 ;</i><br><b>      6</b> <i>en parl. d’événements et de situations,</i> se rencontrer par hasard, <i>d’où en gén</i>. arriver, survenir, avoir lieu, ESCHL. <i>Pers. 802 ;</i> XÉN. <i>Cyr. 5, 5, 19 ;</i> τῶνδε ναμέρτεια σ. SOPH. <i>Tr. 173,</i> la vérification de cet oracle est arrivée ; εἰ καιρὸς σ. XÉN. <i>Hipp. 2, 5,</i> si le moment arrive ; ἄν τι συμϐῇ, DÉM. <i>551, 15,</i> si qqe ch. a lieu, <i>càd</i>. si un délit a été commis ; τοιαῦτα ἀφ' ὧν ἡ ἀσθένεια σ. THC. <i>8, 45,</i> des choses telles que la faiblesse corporelle en est la conséquence (des plaisirs énervants) ; <i>avec le dat</i>. tomber en partage, échoir à, THC. <i>2, 15 ;</i> XÉN. <i>Cyr. 1, 6, 24 ;</i> ᾧ πλεῖσται ψῆφοι συμϐαίνουσι, PLAT. <i>Leg. 756</i> b, à qui la plupart des voix échoient ; σ. τινὶ τριηραρχία, DÉM. <i>1154, 11,</i> le commandement de la trirème échoit à qqn ; <i>avec un dat. suivi d’un inf. :</i> αὐτῷ φεύγοντι Ὀλυμπιάδα ἀνελέσθαι τεθρίππῳ συνέϐη, HDT. <i>6, 103,</i> comme il était en exil, il lui arriva de remporter aux jeux olympiques le prix de la course en char à quatre chevaux ; συνέϐη Γέλωνα νικᾶν, HDT. <i>7, 166,</i> il arriva que Gélon fut vainqueur ; <i>cf</i>. THC. <i>1, 29, etc. ;</i> XÉN. <i>Ages. 5, 3 ; Hell. 7, 1, 31, etc. ;</i> PLAT. <i>Pol. 301</i> e ; <i>avec un dat. accompagné d’un attribut :</i> συμϐέϐηκε τῷ οἰκοδόμῳ μουσικῷ εἶναι, ARSTT. <i>Metaph. 4, 7,</i> il arriva que l’architecte était un habile artiste ; <i>avec un nomin. accompagné d’un inf. :</i> κάθαρσις εἶναι τοῦτο συμϐαίνει, PLAT. <i>Phæd. 67</i> c, il arrive que c’est une purification ; <i>avec un dat. suivi de</i> ὥστε <i>et l’inf</i>. SOPH. <i>Tr. 1152 ; avec un part. :</i> ὀρθῶς σφι ἡ φήμη συνέϐαινε ἐλθοῦσα, HDT. <i>9, 101,</i> le bruit (de la victoire remportée à Platée) se répandit, ainsi que la chose était vraie ; <i>cf</i>. PLAT. <i>Leg. 682</i> d, <i>745</i> e, <i>946</i> c ; <i>Ep. 328</i> a ; <i>Soph. 244</i> d, <i>etc. ; au part. abs</i>. συμϐὰν δὲ ἰδεῖν, SYN. <i>Ep. 66,</i> comme il arriva de voir, <i>etc. ;</i> τὰ συμϐαίνοντα, événements, <i>particul</i>. circonstances accidentelles, cas imprévus, XÉN. <i>Cyr. 1, 6, 43 ; Hell. 7, 1, 24 ;</i> τὰ συμϐάντα, XÉN. <i>An. 3, 1, 13, m. sign. ;</i> τὰ συμϐεϐηκότα, ISOCR. <i>86</i> a, <i>m. sign. ; au sg</i>. τὸ συμϐαῖνον, POL. <i>2, 69, 11, etc. m. sign. ; particul. t. de philos</i>. τὸ συμϐεϐηκός, le caractère non nécessairement attaché à un objet, qualité non essentielle, ARSTT. <i>Metaph. 4, 2, etc. ; Top. 1, 5, etc. Joint à un adv. :</i> σ. καλῶς, EUR. <i>I.T. 1055 ;</i> XÉN. <i>Cyr. 5, 4, 14,</i> arriver heureusement, réussir ; σ. κακῶς, XÉN. <i>Mem. 1, 2, 63,</i> arriver malheureusement, échouer ; <i>abs</i>. arriver heureusement, réussir : ἡ πεῖρα συμϐαίνει, THC. <i>3, 3,</i> l’expérience réussit ; εἴ μοι ξυμϐαίνει τοῦτο, PLAT. <i>Leg. 744</i> a, si la chose me réussit, <i>p. opp. à</i> ἀποτυγχάνω τοῦ σκοποῦ ; <i>en parl. de prédictions,</i> se réaliser, s’accomplir, THC. <i>2, 17 ; p. suite,</i> profiter à, être d’un grand secours à, <i>suivi de</i> ὥστε, THC. <i>4, 79 ;</i><br><b>      7</b> <i>en gén</i>. être, exister, se trouver, PLAT. <i>Crat. 398</i> b ; <i>avec un attribut, au sens de</i> γίγνεσθαι <i>ou</i> εἶναι : ᾗ τὰ μητρὸς ἔχθιστα συμϐέϐηκεν, SOPH. <i>El. 2,</i> à qui la conduite de la mère est échue comme la plus hostile, <i>càd</i>. contre qui la conduite de la mère est devenue hostile au plus haut degré ; ταῦτ' οὖν ἐπειδὴ λαμπρὰ συμϐαίνει, SOPH. <i>Tr. 1174,</i> comme cela donc est maintenant clair ; τοιούτου ξυμϐάντος τούτου, THC. <i>1, 74,</i> cela s’étant produit ainsi ; <i>cf</i>. PLAT. <i>Rsp. 329</i> d, <i>Leg. 655</i> e, <i>etc. ;</i><br><b>      8</b> <i>t. de dialect</i>. s’ensuivre, résulter, PLAT. <i>Gorg. 459</i> b, <i>498</i> e ; <i>avec une prop. inf</i>. PLAT. <i>Theæt. 170</i> c, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. 3 pl. sync</i>. συμϐέϐασι <span>[ᾱ]</span> EUR. <i>Hel. 622 ; inf</i>. συμϐεϐάναι, HDT. <i>3, 146 ; pass. ao</i>. συνεϐάθην <span>[ᾰ]</span> THC. <i>4, 30</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμ-βαινω - συμβαίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 6 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Actes (3)</li>\n<li>1 Corinthiens (1)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4820":"<h1>sumballo</h1>\n<p>Strong n° 4820 <i>Prononciation [soom-bal'-lo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>jeter ensemble, apporter ensemble\n<ol type=\"a\">\n<li>converser</li>\n<li>repasser dans son esprit, conférer avec soi-même</li>\n<li>venir ensemble, rencontrer\n<ol>\n<li>rencontrer dans un sens hostile</li>\n<li>combattre avec quelqu'un</li>\n<li>donner de ses biens, contribuer, aider, secourir</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·ϐάλλω</b>, <i>anc. att</i>. <b>ξυμ·ϐάλλω</b> <span>(<i>f</i>. συμϐαλῶ, <i>ao.2</i> συνέϐαλον, <i>pf</i>. συμϐέϐληκα ; <i>pass. ao</i>. συνεϐλήθην, <i>pf</i>. συμϐέϐλημαι)</span><br><b>A <i>tr</i>.<br>   I</b> jeter ensemble, mettre ensemble, <i>d’où :</i><br><b>      1</b> apporter en masse : κριθὰς ἵπποις, XÉN. <i>An. 3, 4, 31,</i> de l’orge en quantité pour les chevaux ;<br><b>      2</b> réunir, rapprocher : ὕδωρ, IL. <i>4, 453 ; ou</i> ῥοάς, IL. <i>5, 774,</i> réunir leurs eaux <i>ou</i> leur courant, <i>en parl. de deux fleuves ;</i> βλέφαρα ὕπνῳ, ESCHL. <i>Ag. 15,</i> rapprocher les paupières par l’effet du sommeil ; ὄμμα, ESCHL. <i>Ag. 1294,</i> fermer l’œil, <i>en parl. d’un mourant (ttef</i>. ποῖον ὄμμα συμϐαλῶ ; EUR. <i>I.A. 455,</i> de quel œil l’aborderai-je ?) ; σ. δεξιὰς ἀλλήλοις, EUR. <i>I.A. 58,</i> se donner la main mutuellement ; <i>avec un rég. de pers</i>. faire se réunir à d’autres, fournir un contingent de, <i>acc</i>. XÉN. <i>Cyr. 2, 1, 5 ;</i><br><b>      3</b> échanger : πρὸς ἀλλήλας ἱμάτια, AR. <i>Eccl. 446,</i> leurs vêtements les unes avec les autres, se prêter des vêtements les unes aux autres ; λόγους τινί, EUR. <i>I.A. 830 ; ou simpl</i>. συμϐάλλειν τινί, PLUT. <i>M. 222</i> c ; <i>ou</i> πρός τινα, NT. <i>Ap. 4, 15,</i> échanger des paroles avec qqn, s’entretenir avec qqn ; σ. συμϐόλαια πρὸς ἀλλήλους, PLAT. <i>Rsp. 425</i> c, <i>ou abs</i>. σ. πρὸς ἀλλήλους, PLAT. <i>1 Alc. 125</i> d, échanger des conventions les uns avec les autres ; <i>particul</i>. avancer un prêt contre le reçu d’une obligation ; <i>p. suite,</i> avancer, prêter (de l’argent) : τινί, ISOCR. <i>402</i> c, <i>etc</i>. à qqn ; ἐπί τινι, DH. <i>6, 29,</i> sur un gage ; ὁ συμϐάλλων, DH. <i>5, 63,</i> le prêteur, le créancier : οἱ συμϐάλλοντες, DH. <i>2, 75,</i> les parties contractantes ; <i>en mauv. part :</i> σ. πόλεμον, IL. <i>12, 181 ;</i> μάχην τινί, EUR. <i>Bacch. 835,</i> échanger des hostilités, en venir à un combat avec qqn ; ἔπη κακά, SOPH. <i>Aj. 1323,</i> répondre par de mauvaises paroles à de mauvaises paroles ; ἔχθραν τινί, EUR. <i>Med. 44,</i> lutter contre la haine de qqn ;<br><b>   II</b> jeter l’un contre l’autre, mettre aux prises, <i>en parl. de pers</i>. IL. <i>20, 55 ;</i> ἄνδρας φίλους, XÉN. <i>Cyr. 6, 1, 32,</i> des amis ; <i>en parl. d’animaux :</i> ἀλεκτρυόνας, XÉN. <i>Conv. 4, 9,</i> des coqs ; τινά τινι, HDT. <i>3, 32,</i> un animal contre un autre ; <i>avec un inf</i>. τινὰ καί τινα μάχεσθαι, IL. <i>3, 70,</i> une personne avec une autre pour un combat ;<br><b>   III</b> comparer, rapprocher : τινά τινι, HDT. <i>3, 160, etc</i>. comparer une personne à une autre ; τί τινι, HDT. <i>2, 10 ; 4, 99 ;</i> τι πρός τι, HDT. <i>4, 50 ;</i> PLAT. <i>Theæt. 186</i> b, comparer une ch. avec une autre ; <i>à l’inf. abs</i>. ἓν πρὸς ἓν συμϐάλλειν, HDT. <i>4, 50,</i> si l’on compare chaque fleuve à l’autre isolément ; συμϐάλλειν εἰ…, ἤ, ARAT. <i>1146,</i> comparer pour voir si…, ou si, <i>etc. ;</i><br><b>   IV</b> conjecturer, <i>d’où :</i><br><b>      1</b> interpréter, expliquer : τι, SOPH. <i>O.C. 1474 ;</i> EUR. <i>Or. 1394, etc</i>. qqe ch. ; μαντείαν, PLAT. <i>Crat. 384</i> a, une prédiction ; χρησμόν, ARSTT. <i>fr. 489,</i> un oracle ;<br><b>      2</b> supputer, évaluer : ἡ ὁδὸς ἀνὰ διηκόσια στάδια συμϐέϐληταί μοι, HDT. <i>4, 101,</i> j’évalue la route à 200 stades environ ;<br><b>B <i>intr. :</i><br>      1</b> aboutir : εἰς ταὐτόν, PLAT. <i>Pol. 285</i> a, au même point ;<br><b>      2</b> se rencontrer avec : σ. <i>ou</i> ξ. τινί, OD. <i>8, 204 ; 21, 15 ;</i> EUR. <i>Her. 679 ;</i> PLUT. <i>Pel. 12, etc. ;</i> πρός τινα, ESCHL. <i>Ch. 677,</i> avec qqn ; <i>d’où</i> se réunir avec qqn, XÉN. <i>Cyr. 6, 2, 41 ;</i> οἱ συμϐάλλοντες, PLUT. <i>Marc. 20,</i> les gens qui se mettent en relation avec qqn ; <i>avec un suj. de ch. :</i> ἔνθα συμϐάλλουσιν ὁδοί, SOPH. <i>O.C. 901,</i> où se rencontrent les routes ; <i>en parl. d’un fleuve,</i> se jeter dans (un autre) <i>dat</i>. ARR. <i>An. 6, 1, 6 ; avec idée d’hostilité :</i> συμϐάλλειν μάχεσθαι, IL. <i>16, 565 ;</i> συμϐάλλειν εἰς χεῖρας, ATT. ; <i>ou simpl</i>. συμϐάλλειν, HDT. <i>1, 82, 103 ;</i> XÉN. <i>Ages. 2, 7, etc. ;</i> συμϐάλλειν εἰς μάχην, POL. <i>1, 9, 7,</i> en venir aux mains ; <i>ou simpl</i>. σ. τινί, HDT. <i>1, 77, 80, 104, etc. ;</i> ESCHL. <i>Ch. 461 ;</i> POL. <i>10, 37, 4 ;</i> πρός τινα, XÉN. <i>Cyr. 7, 1, 20,</i> en venir aux mains <i>ou</i> à une lutte avec qqn ;<br><b><i>Moy.</i></b> :<br><b>A <i>tr</i>.<br>   I</b> mettre en commun, <i>d’où :</i><br><b>      1</b> mêler : ὕδωρ, HDT. <i>4, 50,</i> ses eaux (à celles d’un autre fleuve), <i>en parl. d’un affluent :</i> δάκρυα δάκρυσι, EUR. <i>Or. 336,</i> répandre larmes sur larmes ;<br><b>      2</b> mettre à la masse : πλείω, XÉN. <i>Œc. 7, 13,</i> une plus grosse somme ; χρήματά τινι, XÉN. <i>An. 1, 1, 9,</i> réunir de l’argent pour qqn ; <i>p. suite</i> contribuer : τινὸς συμϐάλλεσθαι μέρος, DÉM. <i>1031, 14,</i> contribuer pour une part à qqe ch. ; τί μέρος ξυμϐάλοιτ' ἂν πρὸς ἀρετήν ; PLAT. <i>Leg. 836</i> d, en quoi cela contribuerait-il à la vertu ? μέγα μέρος σ. εἴς τι, PLAT. <i>Rsp. 331</i> b, contribuer pour une grande part à qqe ch. ; μέγα συμϐάλλεται εἰς τοῦτο ὅτι, XÉN. <i>Cyr. 1, 2, 8,</i> une raison qui contribue grandement à cela, c’est que, <i>etc. ; p. suite abs</i>. être utile <i>ou</i> profitable à, <i>dat</i>. PLAT. <i>Leg. 905</i> c ; DÉM. <i>558, 13, etc. ;</i><br><b>      3</b> prêter : ὁλκάδα τινί, HDT. <i>3, 135,</i> un vaisseau de charge à qqn ; χρήματά τινι, XÉN. <i>An. 1, 1, 9,</i> de l’argent à qqn ; <i>fig. :</i> βοήθειάν τινι, PLAT. <i>Leg. 836</i> b, assistance à qqn ;<br><b>      4</b> échanger : λόγους περί τινος, XÉN. <i>Cyr. 2, 2, 21,</i> des paroles sur un sujet ; ξενίαν, XÉN. <i>An. 6, 6, 35,</i> échanger des rapports d’hospitalité ; <i>abs</i>. ξυμϐαλέσθαι πρός τινα, THC. <i>5, 77 (docum</i>.) se mettre d’accord avec qqn, conclure un traité avec qqn ;<br><b>      5</b> convenir de : λόφον, XÉN. <i>An. 6, 3, 3,</i> d’occuper une colline (<i>litt</i>. fixer en commun une colline pour l’occuper) ;<br><b>   II</b> rapprocher par la pensée, <i>càd. :</i><br><b>      1</b> supputer, évaluer : ἐπὶ δακτύλῳ τοὺς μῆνας, HDT. <i>6, 63,</i> compter les mois sur son doigt ;<br><b>      2</b> expliquer : γνώμην, HDT. <i>8, 61, etc</i>. expliquer son avis ; γνώμην περί τινος, PLAT. <i>Pol. 298</i> c, son avis sur qqe ch. ; <i>abs</i>. s’expliquer, donner son avis : περί τινος, XÉN. <i>An. 4, 6, 14,</i> sur qqe ch. ;<br><b>      3</b> conjecturer, interpréter, s’expliquer : πρῆγμα, HDT. <i>4, 111,</i> une affaire ; <i>avec un relat. :</i> οὐκ ἔχω συμϐαλέσθαι ἐπ' ὅτευ, <i>etc</i>. HDT. <i>4, 45,</i> je ne puis comprendre pour quel motif, <i>etc. ; abs</i>. ὡς ἐγὼ συμϐάλλομαι, HDT. <i>3, 33,</i> comme je me l’explique ; ὡς ἐγὼ συμϐαλλόμενος εὑρίσκω, HDT. <i>7, 184 ; 8, 30 ; ou à l’inf. abs</i>. ὡς ἐμὲ συμϐαλλόμενον εὑρίσκειν, HDT. <i>7, 24,</i> comme je trouve, tout considéré ; τῇδε συμϐαλλόμενος, HDT. <i>1, 68,</i> remarquant par suite de cela, <i>etc. ; avec une prop. inf</i>. HDT. <i>8, 94 ; ou avec</i> ὅτι, HDT. <i>3, 68,</i> conjecturer <i>ou</i> s’expliquer que, <i>etc. ;</i><br><b>B <i>intr.</i></b> se rencontrer avec, <i>d’où</i> se réunir avec, avoir une entrevue avec, <i>abs</i>. IL. <i>14, 39 ;</i> OD. <i>7, 204 ; 11, 127, etc. ; avec le dat</i>. IL. <i>14, 27, 231 ; 20, 335, etc. ;</i> OD. <i>10, 105, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. 2 sg. épq</i>. συμϐλήσεαι, IL. <i>20, 335 ; ao.2 ind. 3 duel poét</i>. ξυμϐλήτην, OD. <i>21, 15 ; inf. poét</i>. ξυμϐλήμεναι, IL. <i>21, 578. Moy. ao.2 ind. 3 sg. épq</i>. ξύμϐλητο, IL. <i>14, 39, 231 ;</i> OD. <i>6, 54 ; 3 pl</i>. ξύμϐληντο, IL. <i>14, 27 ; 24, 709 ;</i> OD. <i>10, 105 ; sbj. 3 sg</i>. ξύμϐληται, OD. <i>7, 204 ; part</i>. ξυμϐλήμενος, OD. <i>11, 127 ; 15, 441 ; 23, 274 ; 24, 260</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμ-βαλλω - συμβάλλω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Actes (4)</li>\n</ul>\n</td></tr>\n</table>","G4821":"<h1>sumbasileuo</h1>\n<p>Strong n° 4821 <i>Prononciation [soom-bas-il-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>régner ensemble</li>\n<li>métaph. posséder l'honneur suprême, la liberté, la bénédiction dans le royaume de Dieu</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·ϐασιλεύω</b> <span>[ᾰῐ]</span> régner ensemble <i>ou</i> avec, <i>dat</i>. POL. <i>30, 2, 4 ;</i> PLUT. <i>Lyc. 5 ;</i> LUC. <i>D. deor. 16, 2, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμ-βασιλευω - συμβασιλεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n<li>2 Timothée (2)</li>\n</ul>\n</td></tr>\n</table>","G4822":"<h1>sumbibazo</h1>\n<p>Strong n° 4822 <i>Prononciation [soom-bib-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire fusionner, joindre ensemble, assembler, renforcer la cohésion de\n<ol type=\"a\">\n<li>unir ou lier ensemble : dans l'affection</li>\n</ol>\n</li>\n<li>rassembler dans son esprit\n<ol type=\"a\">\n<li>comparer</li>\n<li>recueillir, conclure, considérer</li>\n</ol>\n</li>\n<li>unir une personne avec une autre dans une conclusion ou l'amener à une même opinion, prouver, démontrer\n<ol type=\"a\">\n<li>enseigner, instruire quelqu'un</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·ϐιϐάζω</b> <span>[ῐ]</span><br><b>   I</b> rapprocher, réunir, NT. <i>Eph. 4, 16 ; Col. 2, 19 ; fig</i>. comparer, rapprocher, PLAT. <i>Hipp. mi. 359</i> d, <i>etc. ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> amener à un arrangement, à un traité, réconcilier, HDT. <i>1, 74 ;</i> PLAT. <i>Prot. 337</i> e ; τινά τινι, THC. <i>2, 29,</i> une personne avec une autre ; <i>au pass</i>. ARSTT. <i>Soph. el. 24, 1 ;</i><br><b>      2</b> faire convenir qqn de qqe ch., <i>d’où</i> convaincre, instruire, <i>acc</i>. SPT. <i>Esaï. 40, 14 ;</i> NT. <i>1Cor. 2, 16 ;</i><br><b>      3</b> démontrer par raisonnement, prouver logiquement, <i>acc</i>. ARSTT. <i>Top. 7, 5, 10, etc. ; avec</i> ὅτι, ARSTT. <i>Top. 7, 5, 2 ; avec</i> ὡς, ARSTT. <i>Rhet. Al. 4, 9, etc. ; avec une prop. inf</i>. OCELL. <i>3</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμ-βιβαζω - συμβιβάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4823":"<h1>sumbouleuo</h1>\n<p>Strong n° 4823 <i>Prononciation [soom-bool-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>donner un conseil</li>\n<li>prendre conseil des autres, tenir conseil ensemble, se consulter, délibérer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·ϐουλεύω</b>, donner un conseil, conseiller, <i>particul. :</i><br><b>      1</b> <i>en parl. d’orateurs qui recommandent au peuple une mesure, une décision, avec un dat. de pers. et un infin</i>. HDT. <i>1, 53, 59, etc. ;</i> THC. <i>1, 65, etc. ; avec un inf. seul,</i> HDT. <i>7, 46 ; avec une prop. inf</i>. PLAT. <i>Prot. 337</i> e ; <i>sans inf. avec double rég. :</i> σ. τινί τι, ATT. conseiller qqe ch. à qqn ; <i>avec un seul rég</i>. σ. τι, HDT. <i>7, 237 ;</i> XÉN. <i>An. 5, 6, 12, etc</i>. conseiller qqe ch. ; <i>abs</i>. ὁ συμϐουλεύων, AND. <i>13, 8 (loi</i>) celui qui conseille, qui propose une décision ;<br><b>      2</b> <i>en gén</i>. conseiller : τινί, THGN. <i>38,</i> qqn ; τινί τι, HDT. <i>1, 71, etc. ;</i> ATT. ; τινὶ περί τινος, PLAT. <i>Prot. 319</i> d, <i>etc</i>. qqe ch. à qqn, donner un conseil à qqn au sujet de qqe ch. <i>avec l’inf</i>. ATT. conseiller de, <i>etc. ; avec un acc. de même sign</i>. σ. συμϐουλάς, PLAT. <i>Gorg. 520</i> d, donner des conseils ; <i>au pass</i>. être conseillé, <i>avec un suj. de chose,</i> PLAT. <i>Ep. 330</i> d, <i>etc. ;</i><br><b><i>Moy.</i></b> délibérer avec : τινι, HDT. <i>2, 107 ;</i> XÉN. <i>An. 2, 1, 17,</i> avec qqn ; τι, THC. <i>8, 68,</i> sur qqe ch. ; <i>ou</i> τι μετά τινος, AR. <i>Nub. 475,</i> avec qqn sur qqe ch. ; τινι περί τινος, PLAT. <i>Prot. 319</i> d, <i>etc</i>. avec qqn au sujet de qqe ch.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμ-βουλευω - συμβουλεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Jean (2)</li>\n<li>Actes (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4824":"<h1>sumboulion</h1>\n<p>Strong n° 4824 <i>Prononciation [soom-boo'-lee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le conseil, qui est donné, pris, entériné\n<ol type=\"a\">\n<li>consulter, délibérer</li>\n</ol>\n</li>\n<li>un conseil\n<ol type=\"a\">\n<li>une assemblée de conseillers ou personnes en consultation (les gouverneurs et procurateurs de provinces avaient un conseil d'assesseurs dont ils prenaient l'avis avant de rendre le jugement)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμϐούλιον, ου (τὸ) :<br>      1</b> conseil, PLUT. <i>Rom. 14 ;</i> NT. <i>Matth. 12, 14 ; Marc. 3, 6 ;</i><br><b>      2</b> délibération, DC. <i>38, 42 ;</i><br><b>      3</b> assemblée délibérante, PLUT. <i>Luc. 26, etc</i>.<br><span><b>Étym</b>. σύμϐουλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμ-βουλιον - συμβούλιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (2)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4825":"<h1>sumboulos</h1>\n<p>Strong n° 4825 <i>Prononciation [soom'-boo-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un conseiller, celui qui donne un avis</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σύμ·ϐουλος</b>, <i>anc. att</i>. <b>ξύμ·ϐουλος, ου (ὁ, ἡ) :<br>   I</b> <i>en gén. :</i> qui donne un conseil, conseiller, <i>particul</i>. pour les affaires publiques, HDT. <i>5, 24 ; 7, 50 ;</i> THC. <i>3, 42 ;</i> SOPH. <i>Ph. 1321, etc. ; au fém</i>. XÉN. <i>Hell. 3, 1, 13 ; avec un gén. de pers</i>. σ. τινος, ESCHL. <i>Pers. 175 ;</i> AR. <i>Th. 921, etc. ; ou un dat. de pers</i>. σ. τινι, XÉN. <i>Conv. 7, 39, etc</i>. qui donne un conseil à qqn ; <i>avec un gén. de chose :</i> σ. τινος, ESCHL. <i>Pers. 170, etc</i>. qui conseille qqe ch. ; <i>avec une prép. :</i> σ. περί τινος, ESCHL. <i>Ch. 86 ;</i> PLAT. <i>Prot. 319</i> b ; <i>ou</i> ὑπέρ τινος, ISOCR. <i>9</i> d, qui donne un conseil sur qqe ch. ;<br><b>   II</b> <i>particul. :</i><br><b>      1</b> <i>à Athènes, n. des thesmothètes,</i> DÉM. <i>1330, 15 ;</i><br><b>      2</b> <i>à Sparte,</i> conseiller qui assistait le général, THC. <i>5, 63 ;</i><br><b>      3</b> <i>à Thurii,</i> sorte d’officier, ARSTT. <i>Pol. 5, 7, 13 ;</i><br><b>      4</b> <i>à Rome, traduct. du lat</i>. legatus, POL. <i>6, 35, 4 ; ou</i> consul, DH. <i>4, 76</i>.<br><span><b>Étym</b>. σ. βουλή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμ-βουλος - σύμβουλος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4826":"<h1>Sumeon</h1>\n<p>Strong n° 4826 <i>Prononciation [soom-eh-one']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Siméon (Simon) = « qui écoute, qui entend »\n<ol>\n<li>le second fils de Jacob par Léa</li>\n<li>un des descendants d'Abraham</li>\n<li>quelqu'un qui prit l'enfant Jésus dans ses bras dans le temple</li>\n<li>un enseignant dans l'église d'Antioche</li>\n<li>le nom d'origine de Pierre l'apôtre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Συμεων</font> &lt; שמעון - <font face=\"Georgia\">Συμεών</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (3)</li>\n<li>Actes (2)</li>\n<li>2 Pierre (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4827":"<h1>summathetes</h1>\n<p>Strong n° 4827 <i>Prononciation [soom-math-ay-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un compagnon disciple, condisciple</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμμαθητής, οῦ (ὁ)</b> <span>[ᾰ]</span> condisciple, PLAT. <i>Euthyd. 272</i> c ; ANAXIPP. (<i>Com. fr. 4, 459</i>).<br><span><b>Étym</b>. συμμανθάνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμ-ματητης - συμμαθητής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4828":"<h1>summartureo</h1>\n<p>Strong n° 4828 <i>Prononciation [soom-mar-too-reh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>rendre témoignage à, amener un témoin</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμμαρτυρέω</b>, <i>anc. att</i>. <b>ξυμμαρτυρέω-ῶ</b> <span>[ῠ]</span> témoigner avec <i>ou</i> en faveur de : τινί τι, XÉN. <i>Hell. 3, 3, 2,</i> donner à qqn un témoignage favorable ; σ. τινι ὅτι, PLAT. <i>Hipp. ma. 282</i> b ; σ. τινι ὡς, XÉN. <i>Hell. 7, 1, 35, ou abs</i>. σ. ὡς, EUR. <i>I.A. 1158,</i> confirmer la déclaration de qqn en témoignant que, <i>etc. ; avec un relat</i>. ξ. τινι οἷος, <i>etc.,</i> EUR. <i>Hipp. 286,</i> attester quel, <i>etc. ; abs</i>. THC. <i>8, 51 ;</i> SOPH. <i>Ph. 438, El. 1224</i>.<br><span><b>Étym</b>. συμμάρτυρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμ-μαρτυρεω - συμμαρτυρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (3)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4829":"<h1>summerizomai</h1>\n<p>Strong n° 4829 <i>Prononciation [soom-mer-id'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>diviser au même moment, partager ensemble</li>\n<li>attribuer une portion</li>\n<li>diviser avec quelqu'un (comme « une part à moi, une part à toi »)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·μερίζω</b>, donner une part proportionnelle : τινί τι, DH. <i>Rhet. 5,</i> de qqe ch. à qqn ;<br><b><i>Moy.</i></b> :<br><b>      1</b> <i>m. sign</i>. DL. <i>6, 77 ;</i><br><b>      2</b> prendre sa part de, participer à, <i>dat</i>. DS. <i>Exc. 540, 96 ;</i> NT. <i>1Cor. 9, 13</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμ-μεριζομαι - συμμερίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4830":"<h1>summetochos</h1>\n<p>Strong n° 4830 <i>Prononciation [soom-met'-okh-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>partager ensemble avec quelqu'un, un co-partage\n<ol type=\"a\">\n<li>de quelque chose</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·μέτοχος, ος, ον</b>, qui participe à : τινί τινος, JOS. <i>B.J. 1, 24, 6,</i> qui participe à une ch. avec qqn ; <i>subst</i>. celui qui participe à, <i>gén</i>. ARSTT. <i>Plant. 1, 1, 22 ;</i> NT. <i>Eph. 5, 7</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμ-μετοχος - συμμέτοχος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4831":"<h1>summimetes</h1>\n<p>Strong n° 4831 <i>Prononciation [soom-mim-ay-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un imitateur des autres</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμμιμητής, οῦ (ὁ)</b> <span>[ῑ]</span> imitateur avec d’autres, NT. <i>Phil. 3, 17</i>.<br><span><b>Étym</b>. συμμιμέομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμ-μιμητης - συμμιμητής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4832":"<h1>summorphos</h1>\n<p>Strong n° 4832 <i>Prononciation [soom-mor-fos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ayant la même forme qu'une autre, similaire, conforme à</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σύμ·μορφος, ος, ον</b>, de même forme que, conforme à, <i>dat</i>. NIC. <i>Th. 321 ;</i> NT. <i>Phil. 3, 21 ; gén</i>. NT. <i>Rom. 8, 29 ; abs</i>. LUC. <i>Am. 39</i>.<br><span><b>Étym</b>. σ. μορφή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμμορφος - σύμμορφος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – décrit ce qui est l'essence du caractère et ainsi ce qui est complet ou durable, pas simplement une forme ou un aperçu\n<br><br> – conformer une chose à une autre, le mot décrit ce qui est transitoire, changeable, et instable</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4833":"<h1>summorphoo</h1>\n<p>Strong n° 4833 <i>Prononciation [soom-mor-fo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être conforme à, recevoir la même forme que</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμμορφίζω</b>, <i>c</i>. συμμορφόω, NT. <i>Phil. 3, 10 ;</i> BAS. <i>3, 529 Migne</i>.<br><br>\n<b>συμμορφόω-ῶ</b>, rendre semblable, NT. <i>Phil. 3, 10</i>.<br><span><b>Étym</b>. σύμμορφος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμμορφοω - συμμορφίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4834":"<h1>sumpatheo</h1>\n<p>Strong n° 4834 <i>Prononciation [soom-path-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être affecté du même sentiment qu'un autre, sympathiser avec</li>\n<li>compatir avec, avoir de la compassion pour</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμπαθέω</b>, <i>anc. att</i>. <b>ξυμπαθέω-ῶ</b> <span>[ᾰ]</span><br><b>      1</b> prendre sa part de la souffrance d’autrui, éprouver de la compassion, de la sympathie : ἐπί τινι, DH. <i>10, 1 ;</i> τινι, ISOCR. <i>64</i> b ; DH. <i>10, 6 ;</i> PLUT. <i>Cleom. 1, etc</i>. pour qqn <i>ou</i> pour qqe ch. ; <i>abs</i>. PLUT. <i>Tim. 14 ;</i><br><b>      2</b> éprouver les mêmes sentiments <i>ou</i> impressions que, <i>dat</i>. ARSTT. <i>Physiogn. 4, 1 ;</i> ARÉT. <i>Cur. m. diut. 1, 4</i>.<br><span><b>Étym</b>. συμπαθής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμπαθεω - συμπαθέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G4835":"<h1>sumpathes</h1>\n<p>Strong n° 4835 <i>Prononciation [soom-path-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>souffrir ou ressentir comme un autre, être compatissant</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·παθής, ής, ές</b> <span>[ᾰ]</span><br><b>   I</b> <i>intr. :</i><br><b>      1</b> qui prend sa part de la souffrance d’autrui, qui éprouve de la compassion, de la sympathie, PLAT. COM. <i>2-2, 686 Mein. ;</i><br><b>      2</b> <i>p. ext</i>. qui éprouve les mêmes sentiments que, <i>dat</i>. ARSTT. <i>Probl. 19, 40 ;</i> POL. <i>8, 5, 13 ; en parl. de choses (âme, corps,</i> ARSTT. <i>Physiogn. 4, 2 ; nerfs,</i> ANTH. <i>11, 352</i>) ;<br><b>   II</b> <i>tr</i>. qui excite la compassion, la sympathie, DH. <i>2, 45</i>.<br><span>•<i> Cp</i>. συμπαθέστερος, PLAT. COM. <i>l. c. ;</i> M. TYR. <i>7, 4 ;</i> <i>• Sup</i>. συμπαθέστατος, ARSTT. <i>P.A. 2, 7, 19</i>.<br><span><b>Étym</b>. σ. πάθος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμπαθης - συμπαθής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4836":"<h1>sumparaginomai</h1>\n<p>Strong n° 4836 <i>Prononciation [soom-par-ag-in'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>venir ensemble</li>\n<li>venir à l'aide de quelqu'un, venir assister</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>συμ·παραγίγνομαι :<br>      1</b> se présenter <i>ou</i> apparaître en même temps, HDT. <i>4, 199 ;</i><br><b>      2</b> se tenir auprès de, <i>dat</i>. DÉM. <i>1369, 17 ; d’où</i> assister, <i>dat</i>. THC. <i>2, 82 ; 6, 92</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμπαραγινομαι - συμπαραγίνομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4837":"<h1>sumparakaleo</h1>\n<p>Strong n° 4837 <i>Prononciation [soom-par-ak-al-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>appeler ou inviter ou exhorter au même moment ou ensemble</li>\n<li>fortifier, encourager en étant avec les autres</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·παρακαλέω-ῶ</b> <span>[κᾰ]</span><br><b>      1</b> exhorter ensemble : ἐπί τι, PLAT. <i>Rsp. 555</i> a, à qqe ch. ;<br><b>      2</b> inviter en même temps, <i>acc</i>. XÉN. <i>Cyr. 3, 3, 21 ;</i> εἰς τὴν θήραν, XÉN. <i>Cyr. 8, 1, 38,</i> à la chasse ;<br><b>      3</b> invoquer en même temps : σ. θεοὺς σῶσαι τὴν πατρίδα, DIN. <i>98, 28,</i> supplier en même temps les dieux de sauver la patrie ;<br><b>      4</b> demander <i>ou</i> réclamer en même temps : πρέσϐεις, XÉN. <i>Hell. 4, 8, 13,</i> demander aux alliés de joindre leurs ambassadeurs à ceux qu’ils envoyaient eux-mêmes.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμπαρακαλεω - συμπαρακαλέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4838":"<h1>sumparalambano</h1>\n<p>Strong n° 4838 <i>Prononciation [soom-par-al-am-ban'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>emmener ensemble avec</li>\n<li>dans le N.T. prendre quelqu'un comme compagnon</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·παραλαμϐάνω</b>, recevoir <i>ou</i> prendre en outre ensemble, PLAT. <i>Phæd. 65</i> a, <i>etc. ;</i> ARSTT. <i>Nic. 1, 8, 6, etc. ; au pass</i>. ANTICLÉID. (ATH. <i>157</i> f) ; DH. <i>7, 55, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμπαραλαμβανω - συμπαραλαμβάνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (3)</li>\n<li>Galates (2)</li>\n</ul>\n</td></tr>\n</table>","G4839":"<h1>sumparameno</h1>\n<p>Strong n° 4839 <i>Prononciation [soom-par-am-en'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>demeurer ensemble avec</li>\n<li>continuer à vivre ensemble</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·παραμένω</b>, <i>anc. att</i>. <b>ξυμ·παραμένω :<br>      1</b> rester avec qqn pour l’assister, <i>dat</i>. MÉN. <i>4, 164 Meineke ;</i><br><b>      2</b> rester en même temps que, <i>dat</i>. THC. <i>6, 89 ; abs</i>. persister, HPC. <i>Prorrh. 100 ;</i> THC. <i>6, 89</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμπαραμενω - συμπαραμένω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4840":"<h1>sumpareimi</h1>\n<p>Strong n° 4840 <i>Prononciation [soom-par'-i-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être présents ensemble</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>συμ·πάρειμι</b> :<br><b>      1</b> être présent aussi <i>ou</i> en même temps, HPC. <i>V. med. 15 ;</i> XÉN. <i>Lac. 2, 2 ; 12, 3, etc. ;</i><br><b>      2</b> venir au secours de, assister, <i>dat</i>. XÉN. <i>Hell. 4, 6, 1 ; en parl. d’un avocat,</i> DÉM. <i>749, 16</i>.<br><span><b>Étym</b>. εἰμί, être.</span><br><br>\n➁ <b>συμ·πάρειμι</b> <span>(<i>impf</i>. -παρῄειν, <i>f</i>. -πάρειμι, <i>etc</i>.)</span> s’avancer ensemble <i>ou</i> en même temps, XÉN. <i>Hell. 2, 1, 28 ;</i> ESCHN. <i>42, 37</i>.<br><span><b>Étym</b>. εἶμι, aller.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμπαρειμι - συμπάρειμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4841":"<h1>sumpascho</h1>\n<p>Strong n° 4841 <i>Prononciation [soom-pas'-kho]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>souffrir ou ressentir de la peine ensemble</li>\n<li>souffrir de maux (malheurs, persécutions) de la même manière qu'un autre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·πάσχω</b>, <i>anc. att</i>. <b>ξυμ·πάσχω :<br>      1</b> éprouver les mêmes sentiments, PLAT. <i>Charm. 169</i> c ;<br><b>      2</b> sympathiser avec, compatir à, <i>dat</i>. PLAT. <i>Rsp. 605</i> d ; ANTIPH. (<i>Com. fr. 3, 46) ; t. de physiol</i>. sympathiser, <i>en parl. des organes,</i> ARSTT. <i>Physiogn. 1, 2 ;</i> GAL. <i>Hipp. Aph. comm. 18-1, 25</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμπασχω - συμπάσχω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4842":"<h1>sumpempo</h1>\n<p>Strong n° 4842 <i>Prononciation [soom-pem'-po]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>envoyer ensemble avec</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·πέμπω :<br>      1</b> envoyer ensemble <i>ou</i> en même temps : τινά, ESCHL. <i>Suppl. 493,</i> qqn ; <i>fig</i>. τι, PD. <i>I. 5 fin,</i> qqe ch. ; τινά τινι, HDT. <i>8, 104, etc. ;</i> THC. <i>2, 12 ;</i> EUR. <i>I.T. 1208, 1329 ;</i> τινὰ σύν τινι, XÉN. <i>Cyr. 1, 4, 7, ou</i> μετά τινος, XÉN. <i>Hell. 1, 4, 21,</i> avec qqn ;<br><b>      2</b> accompagner : πομπήν, IS. <i>61, 17 ;</i> LYS. <i>137, 23,</i> un cortège.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμπεμπω - συμπέμπω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4843":"<h1>sumperilambano</h1>\n<p>Strong n° 4843 <i>Prononciation [soom-per-ee-lam-ban'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>comprendre tout de suite</li>\n<li>étreindre, embrasser (dans ses bras)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·περιλαμϐάνω</b> (<i>inf. pf. pass</i>. συμπεριειλῆφθαι) :<br><b>      1</b> embrasser, contenir <i>ou</i> renfermer ensemble, <i>acc</i>. PLAT. <i>Tim. 74</i> d ; ARSTT. <i>H.A. 5, 17, 5, etc. ; particul</i>. comprendre dans un traité, PHILIPP. (DÉM. <i>251, 9</i>) ; dans un ouvrage, POL. <i>8, 13, 4, etc. ;</i><br><b>      2</b> embrasser dans son esprit, concevoir, comprendre, <i>acc</i>. ARSTT. <i>Top. 6, 4, 13 ;</i><br><b><i>Moy.</i></b> prendre part en même temps <i>ou</i> ensemble à, <i>gén</i>. LUC. <i>Dom. 4</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμπεριλαμβανω - συμπεριλαμβάνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4844":"<h1>sumpino</h1>\n<p>Strong n° 4844 <i>Prononciation [soom-pee'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>boire avec</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·πίνω</b> <span>[ῑ]</span><br><b>      1</b> boire ensemble, <i>d’où</i> banqueter, festoyer avec : τινί, PLAT. <i>Min. 320</i> a ; <i>ou</i> μετά τινος, HDT. <i>2, 121 ;</i> AR. <i>Ach. 277,</i> avec qqn ; παρά τινι, XÉN. <i>Cyr. 5, 2, 28,</i> festoyer ensemble chez qqn ;<br><b>      2</b> s’imbiber de, boire, <i>en parl. de plantes,</i> TH. <i>H.P. 5, 7, 4</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμπινω - συμπίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4845":"<h1>sumpleroo</h1>\n<p>Strong n° 4845 <i>Prononciation [soom-play-ro'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>remplir complètement\n<ol type=\"a\">\n<li>d'une cale de navire</li>\n</ol>\n</li>\n<li>compléter entièrement, être accompli : du temps</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·πληρόω-ῶ :<br>   I</b> aider à remplir : τινί τι, HDT. <i>8, 1,</i> aider qqn à remplir qqe ch. ;<br><b>   II.1</b> remplir entièrement, PLAT. <i>Leg. 770</i> b ; ARSTT. <i>Meteor. 1, 3, 14, etc. ; particul. en parl. de navires dont on embarque l’équipage au complet,</i> THC. <i>6, 50 ;</i> PLAT. <i>Conv. 202</i> e ; <i>au pass</i>. être complètement rempli, PLAT. <i>Tim. 75</i> a, <i>etc. ;</i><br><b>      2</b> compléter, ARSTT. <i>Gen. et corr. 2, 10, 11 ;</i> PLUT. <i>M. 694</i> d ;<br><b><i>Moy.</i></b> remplir entièrement, <i>acc</i>. PLAT. <i>Tim. 35</i> e, <i>36</i> b.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμπληροω - συμπληρόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4846":"<h1>sumpnigo</h1>\n<p>Strong n° 4846 <i>Prononciation [soom-pnee'-go]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>étouffer, obstruer entièrement\n<ol type=\"a\">\n<li>métaph. la graine de la divine parole semée dans l'esprit</li>\n<li>se presser ou s'attrouper autour de quelqu'un jusqu'à presque l'étouffer</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·πνίγω</b> <span>[ῑγ]</span> <span>(<i>ao.2 pass</i>. συνεπνίγην <span>[ῐ]</span>)</span> étouffer, suffoquer, <i>en parl. de la pression exercée par la foule,</i> NT. <i>Luc. 8, 42 ; fig</i>. NT. <i>Marc. 4, 7 ; Matth. 13, 22, etc. ; au pass</i>. être trop pressé, <i>en parl. d’arbres,</i> TH. <i>C.P. 6, 11, 6</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμπνιγω - συμπνίγω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G4847":"<h1>sumpolites</h1>\n<p>Strong n° 4847 <i>Prononciation [soom-pol-ee'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>possédant la même citoyenneté que les autres, un concitoyen\n<ol type=\"a\">\n<li>des Gentils qui sont reçus dans la communion des saints</li>\n<li>du peuple consacré à Dieu</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·πολίτης, ου (ὁ)</b> <span>[ῑ]</span> concitoyen, EUR. <i>Her. 826 ;</i> EL. <i>V.H. 3, 24 ;</i> NT. <i>Eph. 2, 19</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμπολιτης - συμπολίτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4848":"<h1>sumporeuomai</h1>\n<p>Strong n° 4848 <i>Prononciation [soom-por-yoo'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>aller en voyage ensemble</li>\n<li>venir ensemble, s'assembler</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·πορεύομαι</b>, aller ensemble avec, <i>dat</i>. XÉN. <i>An. 1, 3, 5 ;</i> PLAT. <i>Phædr. 249</i> c, <i>etc. ; abs</i>. EUR. <i>I.T. 1488 ;</i> ἐπί τινι, ARSTT. <i>Nic. 8, 9, 4,</i> pour qqe ch. ; <i>p. suite :</i><br><b>      1</b> se réunir : πρὸς ἀλλήλους εἰς σύλλογον, POL. <i>6, 16, 4,</i> les uns avec les autres en assemblée ;<br><b>      2</b> avoir commerce avec, PLUT. <i>Lyc. 15</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμπορευομαι - συμπορεύομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (3)</li>\n</ul>\n</td></tr>\n</table>","G4849":"<h1>sumposion</h1>\n<p>Strong n° 4849 <i>Prononciation [soom-pos'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>réunion pour boire, amusement\n<ol type=\"a\">\n<li>de la réunion : les invités</li>\n<li>groupes d'invités</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμπόσιον, ου (τὸ) :<br>      1</b> banquet, festin, THGN. <i>298, 496 ;</i> PD. <i>I. 5 (6), 1 ; N. 9, 115 ;</i> HDT. <i>2, 78 ;</i> PLAT. <i>Rsp. 363</i> c ; <i>titre d’ouvrages de Xénophon, Platon, Plutarque, etc. ;</i><br><b>      2</b> <i>collectiv</i>. les convives, PLUT. <i>M. 157</i> d, <i>704</i> d ;<br><b>      3</b> salle de festin, XÉN. <i>Cyr. 8, 8, 10 ;</i> LUC. <i>D. deor. 24, 1 ;</i> CALLIX. (ATH. <i>196</i> b).<br><span><b>Étym</b>. συμπίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμποσιον - συμπόσιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4850":"<h1>sumpresbuteros</h1>\n<p>Strong n° 4850 <i>Prononciation [soom-pres-boo'-ter-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un compagnon</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·πρεσϐύτερος, ου (ὁ)</b> <span>[ῠ]</span> qui est prêtre avec un autre, NT. <i>1Petr. 5, 1 ;</i> BAS. <i>4, 540 ;</i> NAZ. <i>3, 89 edd. Migne</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμπρεσβυτερος - συμπρεσβύτερος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4851":"<h1>sumphero</h1>\n<p>Strong n° 4851 <i>Prononciation [soom-fer'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>porter ou apporter ensemble, réunir, rassembler</li>\n<li>supporter ensemble ou au même moment\n<ol type=\"a\">\n<li>porter avec les autres, aider à porter</li>\n<li>collecter ou contribuer dans le but d'aider</li>\n<li>être utile, être profitable, avantageux, être expédient</li>\n<li>s'accorder, être d'accord</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·φέρω</b> <span>(<i>f</i>. συνοίσω, <i>ao.1</i> συνήνεγκα, <i>ao.2</i> συνήνεγχον, <i>pf</i>. συνενήνοχα ; <i>pass. fut</i>. συνοίσομαι, <i>ao</i>. συνηνέχθην, <i>pf</i>. συνενήνεγμαι)</span><br><b>A <i>tr. :</i><br>   I</b> porter ensemble, <i>d’où :</i><br><b>      1</b> apporter ensemble, réunir, rassembler : διακόσια τάλαντα ἐς τὠϋτό, HDT. <i>3, 92,</i> deux cents talents dans le même endroit ; <i>cf</i>. THC. <i>1, 99 ;</i> νεκροὺς ἐκ τῶν ὁδῶν, XÉN. <i>An. 6, 2, 9 ; 6, 3, 6,</i> rassembler les morts rapportés des routes ; σ. στρατηγήματα πανταχόθεν, XÉN. <i>Mem. 3, 5, 22,</i> recueillir et apprendre les stratagèmes employés ; εἰς ταὐτὸ σ. τί τινι, DÉM. <i>724, 10,</i> jeter pêle-mêle une chose avec une autre. <i>Pass. avec le fut</i>. συνοίσομαι : se rencontrer, se rassembler, <i>p. opp. à</i> διαφέρεσθαι, HÉRACLITE ÉPH. <i>fr. 10</i> (PLAT. <i>Soph. 242</i> e) ; ὁπότ' Αἰγοκερῆϊ συμφέρετ' Ἠέλιος, ARAT. <i>291,</i> toutes les fois que le soleil se rencontre avec la Corne de la Chèvre ; μεγάλῳ κακῷ συνοισόμενος, HDT. <i>6, 50,</i> qui rencontrera (se heurtera contre) un grand malheur ; <i>d’où</i> arriver, se passer, avoir lieu, survenir, THC. <i>7, 44 ;</i> θόρυϐος ξυνηνέχθη, THC. <i>8, 84,</i> il se produisit du tumulte ; συμφέρεταί τινί τι, HDT. <i>6, 86 ; 8, 86 ;</i> LUC. <i>Syr. 27,</i> qqe ch. arrive à qqn ; συμφέρεταί τινι οὐδὲν χρηστόν, HDT. <i>4, 157,</i> il n’arrive rien de bon à qqn, qqn se trouve dans une mauvaise position ; ἐπὶ τὸ βέλτιον τὸ πρᾶγμα τῇ πόλει ξυνοίσεται, AR. <i>Nub. 594,</i> l’affaire prendra une meilleure tournure ; <i>impers</i>. συμφέρεται ἄμεινον, HDT. <i>4, 15 ;</i> ἐπὶ τὸ ἄμεινον, HDT. <i>5, 82, 114 ;</i> ἐς τὸ ἄμεινον, HDT. <i>7, 8,</i> cela arrive pour le mieux ; <i>avec une prop. inf</i>. συνηνείχθη (<i>ion</i>.) τι τοιόνδε γενέσθαι πρῆγμα, HDT. <i>1, 19 ; 5, 33 ; 6, 86 ;</i> THC. <i>1, 23,</i> il arriva que l’affaire tourna ainsi ; συνηνείχθη (<i>ion</i>.) οἱ τυφλὸν γενέσθαι, HDT. <i>2, 111,</i> il arriva qu’il devint aveugle ; <i>cf</i>. THC. <i>8, 83 ;</i><br><b>      2</b> <i>particul. avec un dat. et avec idée d’hostilité,</i> se rencontrer, en venir aux mains, combattre, IL. <i>8, 400 ; 11, 736 ;</i> τινι, ESCHL. <i>Sept. 638 ;</i> PLUT. <i>Sol. 9,</i> avec qqn ; <i>avec l’inf</i>. πτολεμίζειν, HÉS. <i>Sc. 358,</i> pour combattre ;<br><b>      3</b> avoir commerce avec, fréquenter, avoir des relations avec, THCR. <i>Epigr. 7, 2 ;</i> OPP. <i>H. 5, 34, etc. ; particul. en parl. de relations sexuelles,</i> HDT. <i>1, 196 ;</i> τινι, LUC. <i>Herm. 34,</i> avoir des relations intimes avec qqn ;<br><b>      4</b> s’accorder, être d’accord : <i>au phys., càd</i>. être semblable, EUR. <i>El. 527 ; avec un inf</i>. σ. ὡϋτὸς εἶναι, HDT. <i>2, 79,</i> on s’accorde à le regarder comme le même ; <i>au sens mor</i>. s’unir, se mettre d’accord, HÉRACLITE ÉPH. (PLAT. <i>Soph. 242</i> e) ; THC. <i>6, 13 ;</i> DC. <i>37, 55 ; 45, 8 ;</i> ξ. γνώμῃ ὥστε ἀπαλλάσσεσθαι τοῦ πολέμου, THC. <i>4, 65,</i> être d’accord pour mettre fin à la guerre ; <i>avec le dat</i>. EUR. <i>Her. 919 ; avec un suj. de chose :</i> τὤργῳ τοὔνομα συμφέρεται, CALL. <i>Ep. 6, 6,</i> le mot s’accorde avec la chose ; εὖ τοῖς πράγμασι ξυμφέρεσθαι, PLAT. <i>Crat. 419</i> d, s’accommoder des choses ; σ. τοῖς παροῦσι, PLUT. <i>Tim. 15,</i> s’accommoder du présent <i>ou</i> des circonstances ; <i>avec un acc. :</i> σ. τι, HDT. <i>4, 154 ;</i> PLAT. <i>Eryx. 396</i> c, s’accorder en qqe ch. ; τί τινι, PLAT. <i>Tim. 25</i> e, en qqe ch. avec qqe ch. ; <i>en parl. de mœurs, d’usages,</i> HDT. <i>1, 173 ; 2, 80 ; 6, 59, etc. ;</i> σ. περί τινός τινι, <i>4, 13 ;</i> PLAT. <i>Theæt. 152</i> e, s’accorder sur qqe ch. avec qqn <i>ou</i> avec qqe ch. ; <i>avec l’inf</i>. PLAT. <i>Prot. 317</i> a, pour faire qqe ch. ;<br><b>   II</b> porter ensemble <i>ou</i> en même temps, aider à porter :<br><b>      1</b> <i>au propre :</i> ὁ ἵππος τὸ ὅπλον συμφέρει, XÉN. <i>Cyr. 4, 13, 13,</i> le cheval aide à porter les objets d’équipement ;<br><b>      2</b> <i>fig</i>. supporter ensemble, aider à supporter (un malheur, une douleur, <i>etc.) acc</i>. EUR. <i>H.f. 1366, Alc. 369 ;</i> ANT. <i>122, 121 ; avec le gén</i>. EUR. <i>fr. 100 Dind. ; avec double rég</i>. σ. πενίαν τινί, XÉN. <i>An. 7, 6, 20,</i> aider qqn à supporter la pauvreté ; ὀργάς τινι, ESCHL. <i>Eum. 848,</i> supporter la colère avec qqn, <i>càd</i>. pardonner ;<br><b>      3</b> <i>p. suite, abs</i>. aider, assister, être utile <i>ou</i> avantageux, SOPH. <i>El. 946 ;</i> AR. <i>Nub. 590 ;</i> PLAT. <i>Leg. 952</i> a, <i>etc. ; avec un dat</i>. SOPH. <i>Ph. 659 ;</i> XÉN. <i>Œc. 15, 9 ;</i> AR. <i>Eccl. 472, etc. ;</i> DÉM. <i>9, 2 ;</i> τὸ συνήνεικε ποιησάσῃ, HDT. <i>8, 87,</i> ce qui lui réussit ; οὔκ οἱ συνήνεικε τὸ ἔχθος, HDT. <i>9, 37,</i> cette inimitié ne se termina pas heureusement pour lui ; <i>avec le dat. impers. :</i> σ. τῷ βίῳ, AR. <i>Pl. 38,</i> être utile pour la vie ; ναυμαχίᾳ, THC. <i>2, 89,</i> pour un combat naval ; τοῖς πράγμασι, DÉM. <i>665, 17,</i> pour les affaires ; <i>joint à</i> καλῶς, ESCHL. <i>Suppl. 753 ;</i> AR. <i>Ach. 252 ; avec une prép. :</i> σ. ἔς τι, HDT. <i>8, 88 ;</i> THC. <i>2, 89, etc. ;</i> XÉN. <i>Hell. 6, 2, 19 ;</i> πρός τι, THC. <i>3, 44 ;</i> XÉN. <i>Mem. 2, 2, 5 ;</i> PLAT. <i>Rsp. 338</i> c, <i>etc. ;</i> ἐπί τι, AR. <i>Eccl. 475, etc</i>. pour qqe ch., en vue de qqe ch. <i>Impers</i>. συμφέρει, HPC. <i>48 fin ;</i> XÉN. <i>An. 7, 8, 4,</i> cela est utile ; <i>avec un inf. comme suj. :</i> συμφέρει σωφρονεῖν, ESCHL. <i>Eum. 520,</i> il est utile d’être sage ; <i>cf</i>. HDT. <i>8, 88 ;</i> SOPH. <i>El. 1440 ;</i> THC. <i>2, 63 ;</i> XÉN. <i>Œc. 16, 3 ;</i> PLAT. <i>Rsp. 346</i> b, <i>etc. ; avec l’inf. précédé de l’article,</i> XÉN. <i>Mem. 3, 4, 10 ; avec l’inf. sous-entendu :</i> διδάξοντες ὡς ξυνέφερεν (<i>s.-e</i>. διδάσκειν) THC. <i>3, 71,</i> devant les instruire comme cela leur était utile, <i>càd</i>. était conforme à leur intérêt ; <i>cf</i>. THC. <i>1, 123 ; 2, 44 ;</i> XÉN. <i>Ath. 3, 11 ; part</i>. συμφέρων, ουσα, ον, <i>employé adject</i>. utile, avantageux, profitable ; πολλὰ συμφέροντα, SOPH. <i>O.R. 875,</i> beaucoup de choses utiles, avantageuses ; <i>cf</i>. SOPH. <i>O.C. 1186, 1635 ;</i> PLAT. <i>Rsp. 341</i> d, <i>etc. ;</i> ξυμφέρον ἐστί <i>ou</i> γίγνεται = συμφέρει, HÉRACLITE ÉPH. <i>fr. 10</i> (ARSTT. <i>Nic. 8, 2</i>) ; THC. <i>3, 44 ;</i> XÉN. <i>An. 5, 9, 26 ; Œc. 13, 2 ;</i> ISOCR. <i>29</i> d. <i>Subst</i>. τὸ συμφέρον, ce qui est utile <i>ou</i> avantageux, l’utilité <i>ou</i> l’avantage, SOPH. <i>Ph. 926 ;</i> XÉN. <i>Hell. 4, 6, 13 ; Hipp. 9, 1, etc. ;</i> τὰ συμφέροντα, <i>m. sign</i>. PLAT. <i>Rsp. 341</i> c ; ἐς τὸ ξ. καθίστασθαί τι, THC. <i>4, 60,</i> exploiter qqe ch. à son profit ; τὸ ἡμέτερον συμφέρον, XÉN. <i>Cyr. 3, 2, 20,</i> notre intérêt ; περαιτέρω τοῦ ἡμετέρου συμφέροντος, ESCHN. <i>p. 85, 8,</i> plus qu’il ne nous est utile, plus que notre intérêt ne le permet ; <i>avec un gén. :</i> τὰ σ. τῶν λόγων, SOPH. <i>Ph. 131,</i> le profit à tirer de ses paroles ; τὸ ξυμφέρον τινός, PLAT. <i>Rsp. 341</i> a, l’intérêt de qqn ; τὸ τῆς πόλεως συμφέρον, DÉM. <i>273, 24,</i> l’intérêt de l’État ; <i>avec le dat. :</i> τὸ συμφέρον τινί, XÉN. <i>Ath. 1, 13 ;</i> PLAT. <i>Rsp. 341</i> d, <i>etc. ;</i> DÉM. <i>274, 9, etc</i>. l’intérêt de qqn ; <i>de même à l’ao. :</i> τό τῳ ξυνενεγκόν, THC. <i>2, 51, m. sign. ; avec une prép. :</i> τὸ ξ. ἐπί τι, PLAT. <i>Rsp. 342</i> b ; τὰ πρός τι συμφέροντα, XÉN. <i>Mem. 3, 4, 11 ;</i> τὸ σ. εἴς τι, XÉN. <i>Conv. 4, 59 ;</i> PLAT. <i>Rsp. 342</i> a, ce qui est utile <i>ou</i> avantageux pour qqe ch. ;<br><b>   III</b> <i>impers</i>. il se rencontre, il arrive, il se trouve (<i>cf. ci-dessus</i> A, I, 1) <i>avec une prop. inf</i>. HDT. <i>1, 73 ; 2, 117 ; 3, 4, 42, 129, etc. ; avec</i> ὥστε <i>et l’inf</i>. HDT. <i>1, 74 ; 3, 14, 71 ;</i><br><b>B <i>intr.</i></b> se réunir, se rencontrer :<br><b>      1</b> <i>au propre,</i> τὰ συμφέροντα, XÉN. <i>Cyn. 6, 9,</i> chemins qui se réunissent (<i>sel. d’autres,</i> chemins appropriés) ;<br><b>      2</b> <i>fig</i>. convenir, s’accorder avec, être conforme : σιμὴ (γυνὴ) ἄν σοι ἰσχυρῶς συμφέροι, XÉN. <i>Cyr. 8, 4, 21,</i> une femme au nez camus te conviendrait fort ; ξυνοίσειν ὄνομα τοῖς ἐμοῖς κακοῖς, SOPH. <i>Aj. 431,</i> (mon) nom devoir être d’accord avec mes malheurs ; ξυνοίσεις τοῦ θεοῦ τοῖς θεσφάτοις, AR. <i>Eq. 1233,</i> les prédictions du dieu s’appliquent bien à toi ; <i>de même avec</i> πρός <i>et l’acc</i>. XÉN. <i>An. 7, 3, 37 ;</i><br><b>      3</b> se mettre d’accord, consentir, acquiescer, s’accommoder à : τινί, AR. <i>Lys. 166,</i> à qqn ; τοῖς κρείττοσιν, SOPH. <i>El. 1465, etc</i>. s’accommoder à la volonté des puissants ; <i>avec double rég. :</i> πάντα ξ. τινί, EUR. <i>Med. 13,</i> s’accorder en tout avec qqn, <i>p. opp. à</i> διχοστατεῖν.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. ion</i>. συνήνεικα, HDT. <i>1, 73, etc. ; pass. impf. 1 pl. poét</i>. συμφερόμεσθα, HOM. ; <i>ao. ion</i>. συνηνείχθην, HDT. <i>1, 19 ; 2, 111, etc. ;</i> LUC. <i>Syr. 27</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμφερω - συμφέρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n18 fois dans 17 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Jean (3)</li>\n<li>Actes (2)</li>\n<li>1 Corinthiens (6)</li>\n<li>2 Corinthiens (2)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4852":"<h1>sumphemi</h1>\n<p>Strong n° 4852 <i>Prononciation [soom'-fay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>consentir, être d'accord, avouer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σύμ·φημι</b>, <i>anc. att</i>. <b>ξύμ·φημι</b> <span>(<i>f</i>. -φήσω, <i>ao.1</i> συνέφησα, <i>ao.2</i> συνέφην)</span> parler avec <i>ou</i> comme qqn, <i>d’où :</i><br><b>      1</b> être d’accord avec, <i>dat</i>. SOPH. <i>Aj. 278 ;</i> EUR. <i>Hipp. 266 ;</i> XÉN. <i>Cyr. 3, 2, 26, etc. ; abs</i>. ESCHL. <i>Pr. 40 ;</i> SOPH. <i>Ph. 1310, etc. ;</i><br><b>      2</b> consentir à, reconnaître, accorder : τι, XÉN. <i>An. 5, 8, 9 ; Mem. 2, 1, 4, etc. ; Cyr. 4, 5, 34 ;</i> PLAT. <i>Conv. 177</i> e, <i>etc</i>. qqe ch. ; <i>abs</i>. PLAT. <i>Rsp. 523</i> a, <i>Gorg. 500</i> e, <i>Phæd. 102</i> d, <i>etc. ; avec</i> ὅτι, PLAT. <i>Phæd. 64</i> b, <i>etc. ou avec une prop. inf</i>. SOPH. <i>O.R. 553 ;</i> PLAT. <i>Leg. 831</i> b, <i>etc</i>. convenir avec qqn, accorder à qqn que, <i>etc. ;</i><br><b>      3</b> promettre, <i>avec l’inf. fut</i>. XÉN. <i>Hell. 5, 2, 5</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao.1</i> συνέφησα, PLAT. <i>Rsp. 342</i> e, <i>Soph. 236</i> d, <i>etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμφημι - σύμφημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4853":"<h1>sumphuletes</h1>\n<p>Strong n° 4853 <i>Prononciation [soom-foo-let'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>quelqu'un qui est du même peuple, un compagnon compatriote</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμφυλέτης, ου (ὁ)</b> <span>[φῡ]</span> qui est de la même tribu, <i>d’où</i> compatriote, NT. <i>1Thess. 2, 14</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμφυλετης - συμφυλέτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G4854":"<h1>sumphutos</h1>\n<p>Strong n° 4854 <i>Prononciation [soom'-foo-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>congénital, inné, implanté par les oiseaux ou la nature</li>\n<li>ayant poussé ensemble, uni avec, greffer</li>\n<li>parenté, affinité, analogie</li>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σύμφυτος</b>, <i>anc. att</i>. <b>ξύμφυτος, ος, ον</b> <span>[φῠ]</span><br><b>   I</b> né avec, ESCHL. <i>Ag. 107 ; d’où :</i><br><b>      1</b> inné, naturel à, <i>gén</i>. PLAT. <i>Phil. 51</i> d, <i>Def. 413</i> c ; <i>ou dat</i>. PLAT. <i>Leg. 844</i> a, <i>Phæd. 81</i> c ; ARSTT. <i>H.A. 3, 20, 2 ; abs</i>. PD. <i>I. 3, 23 ;</i> PLAT. <i>Rsp. 609</i> a, <i>etc. ;</i><br><b>      2</b> de même nature, de même sorte, ESCHL. <i>Ag. 107 ;</i> PLAT. <i>Phædr. 246</i> a ;<br><b>   II</b> qui croît <i>ou</i> pousse avec, <i>dat</i>. ARSTT. <i>H.A. 5, 32, 4 ; abs</i>. ARSTT. <i>Top. 6, 6, 20</i>.<br><span><b>Étym</b>. συμφύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμφυτος - σύμφυτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4855":"<h1>sumphuo</h1>\n<p>Strong n° 4855 <i>Prononciation [soom-foo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire pousser ensemble</li>\n<li>croître, grandir ensemble, pousser avec</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμ·φύω</b>, <i>anc. att</i>. <b>ξυμ·φύω</b> <span>(<i>ao</i>. συνέφυσα)</span><br><b>   I <i>tr.</i></b> faire croître ensemble, <i>d’où</i> unir en un tout, combiner, PLAT. <i>Conv. 192</i> e, <i>etc. ;</i> ARSTT. <i>Pol. 2, 4, 6, etc. ;</i><br><b>   II</b> <i>intr. (à l’ao.2</i> συνέφυν, <i>au pf</i>. συμπέφυκα, <i>au pl.q.pf. et au moy</i>.) :<br><b>      1</b> naître avec, <i>dat</i>. ARSTT. <i>H.A. 6, 2, etc. ;</i><br><b>      2</b> croître avec <i>ou</i> ensemble, PLAT. <i>Conv. 191</i> a, <i>Tim. 76</i> e, <i>Phædr. 246</i> d, <i>etc. ; d’où</i> se réunir, s’unir, se fondre : ἀλλήλοις, PLAT. <i>Rsp. 588</i> c, les uns avec les autres ; εἰς ταὐτό, PLAT. <i>Rsp. 503</i> b, se fondre en un tout.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμφυω - συμφύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4856":"<h1>sumphoneo</h1>\n<p>Strong n° 4856 <i>Prononciation [soom-fo-neh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être d'accord ensemble, être en harmonie, être en symphonie, être sans discordance</li>\n<li>être d'accord avec quelqu'un en faisant un marché, convenir d'un accord, marchander</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμφωνέω</b>, <i>anc. att</i>. <b>ξυμφωνέω-ῶ :<br>   I</b> <i>au propre :</i><br><b>      1</b> résonner ensemble <i>ou</i> d’accord, PLAT. <i>Rsp. 617</i> b ; ARSTT. <i>Probl. 19, 23 ;</i><br><b>      2</b> exécuter un concert, une symphonie, CALLIX. (ATH. <i>201</i> f), <i>etc. ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> être du même sentiment, être d’accord avec : τινι, PLAT. <i>Phæd. 101</i> d, avec qqn ; σ. τι, TH. <i>C.P. 6, 9, 2 ;</i> ἔν τινι, PLAT. <i>Phædr. 263</i> b, <i>etc. ;</i> ἐπί τινος, ARSTT. <i>Nic. 2, 7, 1 ;</i> περί τινος, DH. <i>2, 47,</i> sur qqe ch. ; <i>au pass</i>. συμφωνεῖται παρὰ τοῖς πλείστοις, DS. <i>1, 20,</i> la plupart s’accordent à penser que, <i>etc. ; avec</i> ὡς, PLAT. <i>Leg. 634</i> e ; <i>ou</i> ὅτι, ARSTT. <i>Mir. 101 ;</i><br><b>      2</b> faire une convention : πρός τινα, XÉN. <i>Hell. 1, 3, 8,</i> avec qqn ; περί τινος, POL. <i>2, 15, 5,</i> au sujet de qqe ch. ; <i>ou</i> τινός τινι, NT. <i>Matth. 20, 13,</i> avec qqn pour qqe ch. ;<br><b>      3</b> <i>en mauv. part,</i> conspirer, ARSTT. <i>Pol. 4, 12, 5 ;</i><br><b><i>Moy.</i></b> s’accorder, être d’accord, TH. <i>C.P. 1, 1, 1 ;</i> DS. <i>3, 65</i>.<br><span><b>Étym</b>. σύμφωνος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμφωνεω - συμφωνέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4857":"<h1>sumphonesis</h1>\n<p>Strong n° 4857 <i>Prononciation [soom-fo'-nay-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>concorde, accord, entente</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμφώνησις, εως (ἡ)</b> accord, consentement, NT. <i>2Cor. 6, 25 ;</i> ORIG. <i>2, 1684 Migne</i>.<br><span><b>Étym</b>. συμφωνέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμφωνησις - συμφώνησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4858":"<h1>sumphonia</h1>\n<p>Strong n° 4858 <i>Prononciation [soom-fo-nee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>musique d'instruments</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμφωνία</b>, <i>anc. att</i>. <b>ξυμφωνία, ας (ἡ) :<br>      1</b> accord de voix <i>ou</i> de sons, symphonie, PLAT. <i>Crat. 405</i> d, <i>Conv. 187</i> b, <i>etc. ;</i><br><b>      2</b> <i>p. suite,</i> concert, ARSTT. <i>Cæl. 2, 9, 3 ;</i><br><b>      3</b> <i>particul</i>. accord musical de deux sons, PLAT. <i>Rsp. 531</i> a ; ARSTT. <i>Probl. 19, 39, etc. ;</i><br><b>      4</b> <i>fig</i>. accord de sentiments, consentement, union, harmonie, PLAT. <i>Leg. 689</i> d, <i>etc. ;</i> ARSTT. <i>Pol. 7, 15, 7, etc. ;</i><br><b>      5</b> <i>p. anal., n. d’un instrument de musique,</i> POL. <i>26, 10, 5, etc</i>.<br><span><b>Étym</b>. σύμφωνος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμφωνια - συμφωνία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4859":"<h1>sumphonos</h1>\n<p>Strong n° 4859 <i>Prononciation [soom'-fo-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>harmonieux, avec accord, sans discordance</li>\n<li>chose sur laquelle on est d'accord, un commun accord</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σύμ·φωνος</b>, <i>anc. att</i>. <b>ξύμ·φωνος, ος, ον :<br>   I</b> qui résonne ensemble, <i>d’où :</i><br><b>      1</b> qui fait écho à, qui redit, SOPH. <i>O.R. 421 ;</i><br><b>      2</b> qui unit sa voix <i>ou</i> ses accords, ANTH. <i>9, 584 ; d’où</i> harmonieux, AR. <i>Av. 221, etc. ; subst</i>. τὸ σύμφωνον (<i>s.-e</i>. γράμμα) GRAMM. consonne ;<br><b>   II</b> qui résonne d’accord, HH. <i>Merc. 51 ;</i> PLAT. <i>Tim. 80</i> a, <i>Leg. 812</i> d ; <i>différ. de</i> ὁμόφωνος, ARSTT. <i>Probl. 19, 16 et 39 ;</i> τὸ σ. <i>c</i>. συμφωνία, PLAT. <i>Phil. 56</i> a ; <i>fig</i>. qui est d’accord, <i>càd. :</i><br><b>      1</b> qui est du même avis, uni de sentiments, PD. <i>P. 1, 136 ;</i> SOPH. <i>O.C. 619 ;</i><br><b>      2</b> qui s’accorde avec, <i>d’où</i> réglé, mesuré, proportionnel, harmonieux, PLAT. <i>Rsp. 531</i> c ; ARSTT. <i>An. 1, 3, 11, etc. ;</i> σ. τινι, PLAT. <i>Rsp. 380</i> c, <i>Gorg. 457</i> c, <i>etc</i>. qui s’accorde avec qqe ch. ; πρός τινα, PLAT. <i>Ep. 332</i> d, avec qqn ; βίος σύμφωνος τοῖς λόγοις πρὸς τὰ ἔργα, PLAT. <i>Lach. 188</i> d, vie où les paroles sont d’accord avec les actes ;<br><b>      3</b> réglé par un accord convenu : ἵνα σύμφωνον ᾖ τούτοις πρὸς ἐκείνους, POL. <i>6, 36, 5,</i> pour que cela soit des uns aux autres un signe de reconnaissance ; τὸ σ. ARR. <i>Epict. 1, 19, 27,</i> accord, convention, reconnaissance ;<br><b>   III</b> qui convient à la voix, <i>d’où subst</i>. ἡ σ. ARÉT. <i>Cur. m. diut. 2, 5 ;</i> GAL. <i>2, 265,</i> sorte de remède contre la toux.<br><span>•<i> Sup</i>. συμφωνότατος, NICOM. <i>Harm. p. 11</i> a.<br><span><b>Étym</b>. σ. φωνή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμφωνος - σύμφωνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4860":"<h1>sumpsephizo</h1>\n<p>Strong n° 4860 <i>Prononciation [soom-psay-fid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>supputer, estimer, compter, évaluer</li>\n<li>voter avec quelqu'un</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συμψηφίζω</b>, compter ensemble, NT. <i>Ap. 19, 19 ;</i><br><b><i>Moy.</i></b> voter avec, être d’accord avec, <i>dat</i>. AR. <i>Lys. 142</i>.<br><span><b>Étym</b>. σύμψηφος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμψηφιζω - συμψηφίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4861":"<h1>sumpsuchos</h1>\n<p>Strong n° 4861 <i>Prononciation [soom'-psoo-khos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>d'un même esprit, d'un commun accord</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σύμ·ψυχος, ος, ον</b> <span>[ψῡ]</span> uni de sentiments, NT. <i>Phil. 2, 2</i>.<br><span><b>Étym</b>. σ. ψυχή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συμψυχος - σύμψυχος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4862":"<h1>sun</h1>\n<p>Strong n° 4862 <i>Prononciation [soon]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>avec</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σύν</b>, <i>anc. att</i>. <b>ξύν</b>, <i>adv. et prép. ;</i><br><b>A</b> <i>adv. :</i><br><b>      1</b> ensemble, tous ensemble : κενεὰς σὺν χεῖρας ἔχοντες, OD. <i>10, 42,</i> tous ensemble avec les mains vides ;<br><b>      2</b> en même temps, <i>d’ord. joint à des particules copul</i>. δέ <i>et</i> τέ ; σὺν δέ, et en même temps, avec cela, IL. <i>23, 879 ;</i> σύν τε, <i>m. sign</i>. IL. <i>10, 8, 224 ; en ce sens dans les Livres saints, placé entre le verbe et son rég. :</i> ἐμίσησα σὺν τὴν ζωήν, SPT. <i>Eccl. 2, 17,</i> en même temps j’ai haï la vie ; ἔκτισεν ὁ θεὸς σὺν τὸν οὐρανὸν καὶ σὺν τὴν γῆν, AQU. <i>Gen. 1, 1,</i> Dieu créa en même temps le ciel, et en même temps aussi la terre, <i>etc. ;</i><br><b>      3</b> <i>p. suite,</i> en outre, <i>avec une partic. :</i> ξὺν δέ, ESCHL. <i>Ag. 586 ;</i> SOPH. <i>Ant. 85, etc. ; postér</i>. σὺν καί, même avec, en outre aussi, A. RH. <i>1, 74, 843 ;</i><br><b>B</b> <i>prép. avec le dat</i>. avec :<br><b>   I</b> <i>avec un rég. de pers., d’où :</i><br><b>      1</b> <i>propr</i>. avec : σὺν Μενελάῳ, IL. <i>3, 206,</i> avec Ménélas ; σὺν ἀμφιπόλοισι, OD. <i>6, 92,</i> avec ses serviteurs ; σὺν πολλῇ χερί, EUR. <i>Her. 1035,</i> avec une troupe nombreuse ; σὺν τῷ λοιπῷ στρατῷ, HDT. <i>8, 101,</i> avec le reste de l’armée ; παιδεύεσθαι σύν τινι, XÉN. <i>An. 1, 9, 2,</i> être élevé avec qqn ;<br><b>      2</b> <i>p. suite,</i> du côté de, en faveur de : γίγνεσθαι σύν τινι, être <i>ou</i> se mettre du côté de qqn, XÉN. <i>Cyr. 3, 2, 22 ; 7, 5, 77, etc. ;</i> appartenir à un genre, XÉN. <i>Mem. 1, 2, 33 ;</i> αἱ ψῆφοι γίγνονται σύν τινι, XÉN. <i>Conv. 5, 10,</i> les suffrages (cailloux) sont pour qqn ; οἱ σύν τινι, ATT. l’entourage, <i>ou</i> le parti de qqn ;<br><b>      3</b> d’accord avec, en communauté avec : φράζεσθαι σύν τινι, IL. <i>9, 346,</i> délibérer avec qqn, conférer avec qqn ; <i>comme</i> βουλεύεσθαι σύν τινι, ATT. <i>m. sign. ; cf</i>. IL. <i>9, 615 ; 10, 19, etc. ;</i> OD. <i>9, 332 ; 13, 303, etc. ;</i> ἐκπέρθειν πτολίεθρον σύν τινι, IL. <i>13, 379,</i> combattre avec qqn pour détruire une ville ; λοχησάμενος σὺν ἑταίρῳ, OD. <i>13, 268,</i> ayant tendu une embuscade avec un compagnon ; μάχεσθαι σύν τινι, XÉN. <i>Cyr. 5, 3, 5,</i> combattre contre qqn ; πολεμεῖν σύν τινι, XÉN. <i>Hell. 4, 1, 34,</i> faire la guerre comme allié <i>ou</i> auxiliaire de qqn (<i>en ce sens d’ord</i>. μετά τινος, <i>v</i>. μετά) ; σὺν θεῷ, IL. <i>9, 49 ;</i> σὺν θεοῖσιν, IL. <i>24, 430 ;</i> σὺν Ἀθήνῃ, IL. <i>3, 439 ;</i> OD. <i>19, 2, etc. ;</i> σὺν Ἀθήνῃ καὶ Διΐ, IL. <i>20, 192,</i> avec l’aide de la divinité, des dieux, d’Athènè et de Zeus ; σὺν τῷ θεῷ, SOPH. <i>Aj. 383,</i> selon la volonté du dieu ; σὺν θεῷ εἰρημένον, HDT. <i>1, 86,</i> dit par une inspiration divine ; <i>cf</i>. PLAT. <i>Theæt. 151</i> b, <i>Ep. 320</i> b, c, <i>etc. ;</i><br><b>   II</b> <i>avec un rég. de chose :</i><br><b>      1</b> avec : σὺν τεύχεσιν, IL. <i>3, 29 ; 4, 419 ; 8, 530 ; 9, 80 ;</i> IL. <i>10, 182, etc. ;</i> σὺν ἔντεσιν, IL. <i>13, 331 ;</i> σὺν ἔντεσι, IL. <i>6, 418, etc</i>. avec ses armes, avec leurs armes ; σὺν δουρί, IL. <i>15, 541 ;</i> ξὺν δουρί, IL. <i>16, 864 ;</i> σὺν ἔγχεϊ, IL. <i>20, 493,</i> avec sa javeline ; σὺν φόρμιγγι, IL. <i>9, 194,</i> avec une lyre ; σὺν πυρί, IL. <i>15, 744,</i> avec du feu ; σὺν νηΐ, IL. <i>1, 389, etc. ;</i> OD. <i>1, 182 ; 3, 61, etc</i>. avec un vaisseau, sur un vaisseau ; σὺν νηυσί, IL. <i>1, 179 ; 2, 76, etc.,</i> avec, sur la flotte ; <i>de même chez les Att. :</i> σὺν ναυσί, XÉN. <i>An. 3, 2, 12 ; Hell. 2, 2, 7, m. sign. ; avec un n. abstr</i>. σὺν μεγάλῃ ἀρετῇ ἄκοιτιν, OD. <i>24, 193,</i> épouse douée d’un grand mérite ; <i>cf</i>. PD. <i>P. 1, 61 ;</i><br><b>      2</b> par le moyen de, au moyen de : σὺν νεφέεσσι κάλυψεν γαῖαν καὶ πόντον, OD. <i>5, 293,</i> il couvrit de nuages la terre et la mer ; σὺν ἐλαίῳ φαρμακοῦν, PD. <i>P. 4, 221,</i> assaisonner avec de l’huile ; σὺν ποδῶν χειρῶν τε σθένει, PD. <i>N. 10, 48,</i> par la force des pieds et des mains ; πλοῦτον ἐκτήσω σὺν αἰχμῇ, ESCHL. <i>Pers. 755,</i> tu as acquis des richesses à la pointe de la lance ; ἡ τῶν φίλων κτῆσίς ἐστιν οὐδαμῶς σὺν τῇ βίᾳ, ἀλλὰ μᾶλλον σὺν τῇ εὐεργεσίᾳ, XÉN. <i>Cyr. 8, 7, 13,</i> on se fait des amis nullement par la contrainte, mais plutôt en rendant des services ; <i>cf</i>. THC. <i>1, 84, etc. ;</i><br><b>      3</b> en même temps que : ἄνεμος σὺν λαίλαπι πολλῇ, IL. <i>17, 57,</i> du vent avec un fort ouragan ; αὐτῇ σὺν πήληκι κάρη, IL. <i>14, 498,</i> la tête avec le casque lui-même ; σὺν ὄλϐῳ, PD. <i>O. 2, 36,</i> avec le bonheur ; σὺν πότμῳ εὐδαίμονι, PD. <i>O. 2, 18,</i> sous un destin favorable ; θεοῦ σὺν παλάμᾳ, PD. <i>O. 11, 21,</i> avec le concours du dieu ; σὺν θεοῦ τύχᾳ, PD. <i>N. 6, 25,</i> d’après l’arrêt du dieu ; σὺν τιμᾷ θεῶν, PD. <i>P. 4, 51,</i> par la préférence divine ; σὺν θεῶν τιμαῖς, PD. <i>P. 4, 260,</i> par le bienfait divin ; σὺν ἀναγκαίᾳ, PD. <i>P. 1, 51,</i> sous l’influence du besoin, dans le besoin ; σὺν φιλοφροσύναις δέχεσθαι, PD. <i>O. 6, 98,</i> accueillir amicalement ; σὺν εὐμενίᾳ δέχεσθαι, PD. <i>P. 12, 4,</i> accueillir avec bonté ; σὺν δίκᾳ, PD. <i>P. 9, 96,</i> avec justice ; <i>de même chez les</i> ATT. : σὺν τῷ δικαίῳ, XÉN. <i>An. 2, 6, 18,</i> conformément à la justice ; ξὺν νόμῳ <i>ou</i> ξὺν τῷ νόμῳ, ATT. en conformité avec la loi, selon la loi ; σὺν ἀληθείᾳ, σὺν τῷ ἀληθεῖ, ATT. conformément à la vérité, véritablement ; σὺν τῷ ἀγαθῷ, ATT. avec avantage, à l’avantage de, <i>etc. ;</i> σὺν ζημίᾳ, ATT. au désavantage, au préjudice de, <i>etc. ;</i> σὺν τύχῃ, ATT. avec bonheur ; σὺν τάχει, ATT. en hâte ; σὺν ὀργῇ, ATT. avec colère ; σὺν φόϐῳ, ATT. par crainte ; σὺν δόξῃ, PLUT. <i>Alex. 18,</i> glorieusement, honorablement ; <i>avec idée de temps :</i> ἄκρᾳ σὺν ἑσπέρᾳ, PD. <i>P. 11, 10,</i> tard dans la soirée ; καιρῷ σὺν ἀτρεκεῖ, PD. <i>P. 8, 7,</i> au moment favorable ; σὺν τῷ χρόνῳ προϊόντι, XÉN. <i>Cyr. 7, 8, 6,</i> avec la marche du temps ;<br><b>C</b> <i>Place de</i> σύν : σύν <i>se place d’ord. avant son rég. (v. ci-dessus) ; en poésie, qqf. après,</i> IL. <i>10, 19 ;</i> OD. <i>9, 332 ; 13, 103, 258 ; 15, 410 ;</i> PD. <i>P. 8, 7, etc. ; il peut se placer entre un adj. et un subst</i>. IL. <i>9, 144, etc. ;</i> OD. <i>11, 358, etc. ; rar. entre un subst. et un adj</i>. OD. <i>13, 258 ;</i> PD. <i>P. 8, 9, etc. ;</i><br><b>D</b> <i>en comp. σύν marque :</i><br><b>      1</b> <i>la réunion de plusieurs personnes ou de plusieurs choses en un même lieu</i> (<i>v</i>. σύνειμι, συνίστημι, <i>etc.) ; avec idée de mouv</i>. (<i>v</i>. συνάγω, συγκαλέω, <i>etc.) ; ou dans le même temps</i> (<i>v</i>. σύγχρονος, <i>etc</i>.) ;<br><b>      2</b> <i>une communauté d’action</i> (<i>v</i>. συμϐουλεύομαι, συμμάχομαι, <i>etc</i>.) ;<br><b>      3</b> <i>une idée d’ensemble, de rassemblement</i> (<i>v</i>. συγκαλύπτω, συμπληρόω, <i>etc</i>.).<br><span><b><span class=\"arrow\"></span></b> <i>Dans Hom</i>. ξύν <i>seul. quand la finale précéd. a besoin d’être allongée,</i> IL. <i>6, 372 ; 15, 26 ; 16, 248, 864 ;</i> OD. <i>1, 182 ; 3, 105, 302 ; 10, 268 ; 15, 410. Dans les inscr. att. ξύν domine jusqu’au commenc. du 5<sup>e</sup> siècle. av. J.C. ;</i> σύν <i>à partir du 5<sup>e</sup> siècle dans la proport. suiv. : de 460 à 410 av. J.C. 75 ex. de ξύν contre 21 de</i> σύν ; <i>de 410 à 403 av. J.C. 9 ex. de ξύν contre 50 de</i> σύν ; <i>à partir de 403 av. J.C. on ne rencontre plus ξύν que dans les composés, c</i>. ξυνάρχοντες, ξυμϐάλλεσθαι, ξύμϐολον, ξυμϐολή ; <i>à partir de 378 av. J.C. ξύν disparaît même de ces composés, et ne se maintient plus que dans la formule :</i> γνώμην δὲ ξυμϐάλλεσθαι τῆς βουλῆς εἰς τὸν δῆμον ὅτι δοκεῖ τῇ βουλῇ, <i>jusqu’au 1<sup>er</sup> siècle av. J.C., v. Meisterh. p. 181 ; sur l’emploi de μετά avec</i> σύν, <i>v</i>. μετά.<br><span><b>Étym</b>. <i>inconnue ; cf</i>. μεταξύ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συν - σύν</font>\n<br><br>une préposition primaire d'union</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Préposition</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n123 fois dans 119 versets de 15 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (5)</li>\n<li>Luc (22)</li>\n<li>Jean (2)</li>\n<li>Actes (51)</li>\n<li>Romains (4)</li>\n<li>1 Corinthiens (7)</li>\n<li>2 Corinthiens (6)</li>\n<li>Galates (4)</li>\n<li>Ephésiens (2)</li>\n<li>Philippiens (4)</li>\n<li>Colossiens (7)</li>\n<li>1 Thessaloniciens (4)</li>\n<li>Jacques (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4863":"<h1>sunago</h1>\n<p>Strong n° 4863 <i>Prononciation [soon-ag'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>recueillir ensemble, rassembler\n<ol type=\"a\">\n<li>tirer ensemble, collecter\n<ol>\n<li>de poissons</li>\n<li>d'un filet dans lequel ils sont pris</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>amener ensemble, assembler, rassembler\n<ol type=\"a\">\n<li>joindre ensemble, rejoindre quelqu'un (de ceux antérieurement séparés)</li>\n<li>réunir ensemble par convocation</li>\n<li>être assemblés c.à.d. venir ensemble, se rassembler, se rencontrer</li>\n</ol>\n</li>\n<li>amener avec soi\n<ol type=\"a\">\n<li>dans sa maison, c.à.d. recevoir avec hospitalité</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·άγω</b>, <i>anc. att</i>. <b>ξυν·άγω</b> <span>(<i>f</i>. -άξω, <i>ao.2</i> συνήγαγον, <i>pf</i>. συνῆχα, <i>réc</i>. συναγήοχα ; <i>pass. ao</i>. συνήχθην, <i>pf</i>. συνῆγμαι)</span> <span>[ᾰγ]</span><br><b>A <i>tr</i>.<br>   I</b> conduire ensemble, rassembler ; <i>p. opp. à</i> σχίζειν καὶ διασπᾶν, PLAT. <i>Phil. 23</i> e ; σ. τριήρεις καὶ πεζὴν στρατιάν, ISOCR. <i>242</i> d, rassembler des trirèmes et une armée de terre ; νεφέλας, OD. <i>5, 291,</i> rassembler des nuages ; τοὺς αἰχμαλώτους, XÉN. <i>An. 3, 5, 14,</i> réunir les prisonniers ; ξ. θιάσους, XÉN. <i>Mem. 3, 3, 12,</i> former des thiases ; σύλλογον, DÉM. <i>431, 25,</i> réunir une assemblée ; τὰ δικαστήρια πρός τι, LUC. <i>Abd. 10,</i> convoquer les tribunaux ; <i>abs</i>. σ. εἰς ἀποθήκας, NT. <i>Matth. 6, 26,</i> amasser dans les granges ; <i>au pass</i>. se réunir, se rassembler, DÉM. <i>1263, 6 ;</i> NT. <i>Matth. 13, 2, etc. ; particul. :</i><br><b>      1</b> <i>en parl. de parenté, d’amitié,</i> HH. <i>Merc. 507 ;</i> ESCHL. <i>Sept. 756 ;</i> σ. τινά τινι, XÉN. <i>Cyr. 5, 3, 20,</i> unir une personne à une autre ; ἀνθρώπους ἐς κηδείαν, XÉN. <i>Mem. 2, 6, 37,</i> unir les hommes en parenté ; ἡ φύσις σ. τὸ ἄρρεν πρὸς τὸ θῆλυ, ARSTT. <i>Mund. 5, 3,</i> la nature unit le mâle à la femelle ; σ. εἰς οἰκίαν, SPT. <i>Judith 19, 15, 18 ; 2 Sam. 11, 27,</i> accueillir en hôte ; <i>abs</i>. NT. <i>Matth. 25, 35, 38, 43 ; p. suite,</i> réconcilier, DÉM. <i>1335, 30 ; 1360, 6, etc. ;</i><br><b>      2</b> <i>en parl. d’une assemblée délibérante,</i> XÉN. <i>Cyr. 2, 1, 10 ; An. 1, 3, 9, etc. ;</i> τινὰς ἔς τι, THC. <i>1, 120 ;</i> σ. τὴν ἐκκλησίαν τινὸς ἕνεκα, THC. <i>2, 60 ;</i> περί τινος, XÉN. <i>Hell. 7, 1, 27,</i> convoquer une réunion, l’assemblée pour qqe ch. ;<br><b>      3</b> <i>en parl. d’armées,</i> ESCHL. <i>Pers. 508 ;</i> στράτευμα, στρατόν, XÉN. <i>Hell. 3, 1, 5 ; 4, 2, 16, etc</i>. rassembler une armée ; <i>particul</i>. concentrer une armée, <i>p. opp. à</i> διασκηνοῦν, XÉN. <i>An. 4, 4, 10 ; avec idée d’hostilité :</i> συνάγειν εἰς χεῖρας, PLUT. <i>Popl. 9,</i> en venir aux mains ;<br><b>      4</b> <i>fig</i>. rassembler par la pensée : Κρέοντα καὶ Τειρεσίαν, PLAT. <i>Ep. 311</i> a, Créon et Tirésias ; <i>cf</i>. STR. <i>470 ; d’où en gén</i>. rassembler dans un discours, dans un écrit : τι, XÉN. <i>Mem. 3, 10, 2, etc. ;</i> PLAT. <i>Phil. 25</i> d, <i>etc</i>. qqe ch. ; πράξεις καὶ μάχας, ISOCR. <i>285</i> b, <i>etc</i>. le récit de faits et de combats ; ὑπόμνημα τῶν γεγονότων, LUC. <i>H. conscr. 16,</i> un souvenir des événements accomplis ;<br><b>      5</b> <i>fig</i>. σ. ἑαυτόν, se ramasser en soi-même, se concentrer, PLUT. <i>Phil. 20, M. 564</i> d, <i>etc., en parl. de l’âme :</i> ἑαυτὴν συνάγουσα καὶ ἀθροίζουσα πρὸς ἑαυτήν, MARIN. <i>V. Procl. 1, 2, 5,</i> se concentrant et se resserrant en elle-même ; <i>au pass</i>. συνηγμένος, serré <i>ou</i> concis dans le discours, DL. <i>4, 33 ;</i><br><b>      6</b> <i>t. d’arithm</i>. faire le total, DH. <i>4, 6 ;</i> PTOL. <i>Math. synt. t. 2, p. 191 ;</i><br><b>      7</b> <i>t. de log</i>. tirer la conclusion, conclure, déduire, LUC. <i>H. conscr. 17 ;</i> ARR. <i>Epict. 1, 7, 12 ;</i> σ. τὸ κεφάλαιον, ARSTT. <i>Metaph. 7, commenc</i>. récapituler ; <i>cf</i>. SEXT. <i>P. 2, 149, etc. ; avec</i> ὅτι, SEXT. <i>P. 1, 106, 137 ; avec l’inf</i>. LUC. <i>H. conscr. 16 ;</i><br><b>      8</b> venir à bout de, effectuer, établir, organiser : βουλὴν πολέμοιο, BATR. <i>134,</i> un projet de guerre ; γάμους, XÉN. <i>Conv. 4, 64,</i> un mariage ; συμπόσια, STR. <i>640,</i> des banquets ; ἀπὸ συμϐολῶν, DIPH. <i>et</i> EUPHRON (<i>Com. fr. 4, 395 ; 486</i>) un banquet par écot ; σ. δυνάμεις τῇ πόλει, DÉM. <i>305, 8,</i> acquérir des ressources pour la ville ; (τινὶ) φθόνον, DÉM. <i>524, 1 ;</i> μῖσος, PHYLARQ. (ATH. <i>261</i> b) attirer l’envie, la haine sur qqn ;<br><b>      9</b> <i>p. suite,</i> amener ensemble, conduire ensemble : ὅρκια πιστὰ θεῶν σ. IL. <i>3, 269,</i> amener les victimes du sacrifice qui doit sceller l’alliance ; σ. μυριάδα ἀνθρώπων ἐς ἕνα χῶρον, HDT. <i>7, 60,</i> une myriade d’hommes dans un même endroit ; τοὺς μεθ' ἑαυτοῦ ὡς ἐς ἐλάχιστον χωρίον, THC. <i>1, 63,</i> réunir ses hommes dans le plus petit espace possible, masser ses troupes ; <i>cf</i>. THC. <i>2, 84 ; 7, 81, etc. ;</i> ἐς τετράγωνον τάξιν τοὺς ὁπλίτας, THC. <i>4, 125,</i> les hoplites en carré :<br><b>      10</b> <i>fig</i>. presser, réduire : σ. τινὰς ἐς κίνδυνον ἔσχατον, APP. <i>Hann. 60,</i> réduire une troupe au plus extrême danger ; <i>au pass</i>. συνάγεσθαι τῷ λιμῷ, POL. <i>1, 18, 7 ;</i> ὑπὸ τοῦ λιμοῦ, POL. <i>1, 84, 9 ;</i> ὑπὸ λιμοῦ, PLUT. <i>Syll. 12,</i> être pressé par la famine ;<br><b>   II</b> amener l’un avec l’autre, <i>d’où :</i><br><b>      1</b> rapprocher, faire se toucher : σ. τὰ τέρματα, HDT. <i>4, 52,</i> rapprocher leurs cours l’un de l’autre, se rapprocher l’un de l’autre à la fin de leur cours, <i>en parl. de deux fleuves ;</i> διφθέρας σ. XÉN. <i>An. 1, 5, 10,</i> rapprocher des peaux ; τὰς ὀφρῦς, contracter <i>ou</i> froncer les sourcils (<i>v</i>. ὀφρύς) ; πόρους, <i>p. opp. à</i> διϊστάναι, T. LOCR. <i>101</i> a, contracter <i>ou</i> resserrer les pores, <i>p. opp. à</i> διάγειν, ARSTT. <i>H.A. 2, 12 ; p. suite,</i> mettre aux prises, <i>acc</i>. EUR. <i>Or. 1640 ;</i><br><b>      2</b> resserrer, rétrécir, amincir, rendre pointu : πρῴρην, HDT. <i>1, 194,</i> rétrécir la proue ; <i>au pass</i>. ὕλαις τόπος συναγόμενος, POL. <i>5, 7, 10,</i> lieu resserré par des forêts ; συνάγεσθαι εἰς στενὸν ὑπὸ τῶν ὀρῶν, POL. <i>5, 49, 9,</i> être resserré et rétréci par les montagnes ; εἰς ὀξὺ συνῆκται τὸ ἄκρον (τῆς καρδίας), ARSTT. <i>H.A. 1, 17,</i> l’extrémité du cœur se resserre en pointe ; <i>fig. en parl. du temps,</i> DÉM. <i>1445, 26 ;</i><br><b>   III</b> <i>p. suite :</i><br><b>      1</b> produire en réunissant, en faisant se toucher <i>ou</i> se heurter : σ. ἅμμα, PLAT. <i>Tim. 76</i> a, faire un nœud ; ὕφασμα, PLAT. <i>Pol. 310</i> e, confectionner un tissu ; <i>avec idée d’hostilité :</i> ὑσμίνην, IL. <i>14, 448 ; 16, 764 ;</i> Ἄρηα, IL. <i>2, 381 ; 19, 275 ;</i> ἔριδα, IL. <i>5, 861 ;</i> πόλεμον, HH. <i>Cer. 267,</i> amener une mêlée, un combat ;<br><b>      2</b> conduire en même temps : ἐς τέλος, APP. <i>Civ. 5, 145,</i> au terme ; <i>au pass</i>. se mouvoir avec : συνάγεται τᾷ περιφορᾷ τῶ παντός, T. LOCR. <i>98</i> e, ils se meuvent circulairement avec le tout ;<br><b>B <i>intr.</i></b> se joindre, <i>en mauv. part :</i> εἰς χεῖρας, PLUT. <i>Popl. 9 ;</i> κατὰ χεῖρά τινος, HDN <i>7, 1, 12,</i> en venir aux mains avec qqn ;<br><b><i>Moy.</i></b> <span>(<i>f</i>. συνάξομαι, <i>etc</i>.)</span><br><b>      1 <i>tr.</i></b> rassembler, réunir pour soi, <i>acc</i>. PLUT. <i>Lyc. c. Num. 4 ;</i><br><b>      2 <i>intr.</i></b> se resserrer, se contracter, se refermer (<i>p. opp. à</i> διοίγεσθαι) ARSTT.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. poét</i>. σύναγον <span>[ᾰ]</span> EUR. <i>Bacch. 562 ; dor</i>. συνᾶγον <span>[ᾱ]</span> ESCHL. <i>Sept. 756 ; pf. pass. dor</i>. συνᾶγμαι, T. LOCR. <i>101</i> b.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συναγω - συνάγω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n62 fois dans 62 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (24)</li>\n<li>Marc (5)</li>\n<li>Luc (7)</li>\n<li>Jean (8)</li>\n<li>Actes (11)</li>\n<li>1 Corinthiens (1)</li>\n<li>Apocalypse (6)</li>\n</ul>\n</td></tr>\n</table>","G4864":"<h1>sunagoge</h1>\n<p>Strong n° 4864 <i>Prononciation [soon-ag-o-gay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>synagogue = « assemblée, lieu de réunion »\n<ol>\n<li>être ensemble, rassemblement</li>\n<li>dans le N.T., une assemblée d'hommes</li>\n<li>une synagogue\n<ol type=\"a\">\n<li>assemblée de Juifs rassemblés pour prier, écouter la lecture et l'explication des Ecritures; assemblées qui se tenaient chaque Sabbat et jour de fête; plus tard, nom transféré à une assemblée de chrétiens réunis dans un but religieux</li>\n<li>l'immeuble où se tiennent les assemblées de Juifs. Les synagogues semblent dater de l'exil à Babylone. Du temps de Jésus et des apôtres, chaque ville de Palestine, mais aussi chez les Gentils, avaient une synagogue, lorsque le nombre de Juifs le permettait. Les synagogues servaient également pour juger et infliger des punitions.</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συναγωγή, ῆς (ἡ)</b> <span>[ᾰ]</span><br><b>A</b> action de rassembler, <i>particul. :</i><br><b>   I</b> action de réunir :<br><b>      1</b> <i>en gén. en parl. de pers</i>. POL. <i>4, 7, 6 ;</i> DL. <i>2, 129, etc. ; d’où</i> assemblée, SPT. <i>Ex. 12, 3, etc. ; en parl. de choses,</i> HPC. <i>Off. 744 ;</i> ARSTT. <i>Pol. 6, 1, 1 ;</i> POL. <i>27, 12, 2 ;</i> PLUT. <i>M. 776</i> d ; <i>p. opp. à</i> διαίρεσις, PLAT. <i>Phædr. 266</i> b ;<br><b>      2</b> récolte, POL. <i>1, 17, 9, etc. ;</i> DS. <i>5, 21 ;</i><br><b>      3</b> préparatifs (de guerre) THC. <i>2, 18 ;</i><br><b>      4</b> recueil, collection, ARSTT. <i>Nic. 10, 9, 21 ;</i> DH. <i>2, 27 ;</i> PLUT. <i>M. 1131</i> f, <i>1132</i> f ; LGN <i>fr. 5, 5, 7 ;</i> CIC. <i>Att. 9, 13, 3 ; 16, 5, 5, etc. ;</i><br><b>   II</b> rapprochement, <i>d’où :</i><br><b>      1</b> union, PLAT. <i>Theæt. 150</i> a ;<br><b>      2</b> contraction (du visage, <i>etc</i>.) ISOCR. <i>197</i> d ;<br><b>      3</b> resserrement (d’une troupe) en colonne, <i>p. opp. à</i> ἔκτασις, PLAT. <i>Rsp. 526</i> d ; rapprochement, rétrécissement (de la largeur d’une tour, d’une pyramide, d’une échelle, <i>etc</i>. entre la base et le sommet) APD. POL. <i>38 ;</i> STR. <i>335, 536 ;</i> DS. <i>1, 63 ; 3, 40 ;</i><br><b>      4</b> <i>t. de log</i>. conclusion, ARSTT. <i>Rhet. 2, 23, 30 ; 3, 9, 8 ;</i> SEXT. <i>P. 2, 14 ; 3, 170 ;</i><br><b>B</b> lieu de rassemblement, synagogue, SPT. <i>Gen. 1, 9 ; Esaï. 19, 6 ; 37, 25 ;</i> NT. <i>Luc. 8, 41 ; Ap. 9, 2, etc</i>.<br><span><b>Étym</b>. συνάγω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συναγωγη - συναγωγή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n56 fois dans 56 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (9)</li>\n<li>Marc (8)</li>\n<li>Luc (15)</li>\n<li>Jean (2)</li>\n<li>Actes (19)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G4865":"<h1>sunagonizomai</h1>\n<p>Strong n° 4865 <i>Prononciation [soon-ag-o-nid'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>lutter ensemble avec quelqu'un, aider quelqu'un dans un combat</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·αγωνίζομαι</b>, <i>anc. att</i>. <b>ξυν·αγωνίζομαι</b>, prendre part à une lutte avec, soutenir dans une lutte, combattre pour, secourir, assister, défendre : τινι, THC. <i>1, 143 ;</i> AR. <i>Th. 1061, etc</i>. qqn ; τινι πρός τινα, PLAT. <i>1 Alc. 119</i> e ; ἐπί τινα, DÉM. <i>1053, 2,</i> une personne contre une autre ; τινί τι, DÉM. <i>233, 19, etc</i>. qqn en qqe ch. ; τινι πρός τι, DÉM. <i>231, 21 ; ou</i> εἴς τι, DH. <i>4, 4,</i> qqn en vue de qqe ch. ; τινι δίκην, DÉM. <i>872, 20,</i> défendre qqn dans un procès ; <i>abs</i>. combattre ensemble, du même côté, THC. <i>5, 109 ; fig. en parl. du chœur dans la tragédie,</i> ARSTT. <i>Poet. 18, 21</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συναγωνιζομαι - συναγωνίζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4866":"<h1>sunathleo</h1>\n<p>Strong n° 4866 <i>Prononciation [soon-ath-leh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>lutter en même temps avec un autre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·αθλέω-ῶ :<br>      1</b> lutter d’un commun effort : τινι, avec qqn, NT. <i>Phil. 4, 3 ; ou</i> pour qqe ch. NT. <i>Phil. 1, 27 ;</i><br><b>      2</b> saisir par un effort continu, DS. <i>3, 4 au pass</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συναθλεω - συναθλέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4867":"<h1>sunathroizo</h1>\n<p>Strong n° 4867 <i>Prononciation [soon-ath-royd'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se rassembler ensemble avec les autres</li>\n<li>s'assembler</li>\n<li>être réunis ensemble c.à.d. venir ensemble</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·αθροίζω</b>, <i>anc. att</i>. <b>ξυν·αθροίζω</b>, rassembler, réunir, <i>acc</i>. (une armée, XÉN. <i>An. 7, 2, 8 ;</i> une flotte ; LYS. <i>194, 2 ;</i> des personnes, PLAT. <i>Tim. 44</i> d, <i>etc</i>.) ; εἰς ἕν, AR. <i>Lys. 585,</i> en un tout ; <i>d’où au pass. :</i><br><b>      1</b> se rassembler, se serrer, THC. <i>2, 99 ;</i> XÉN. <i>An. 6, 5, 30 ;</i> PLAT. <i>Rsp. 422</i> d, <i>etc. ;</i> εἰς ἕν, PLAT. <i>Tim. 25</i> b, se réunir en un tout ;<br><b>      2</b> <i>poét. en parl. d’une seule pers</i>. se joindre à, rallier, <i>dat</i>. EUR. <i>Rhes. 613</i>.<br><span><b>Étym</b>. σ. ἁθροίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συναθροιζω - συναθροίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4868":"<h1>sunairo</h1>\n<p>Strong n° 4868 <i>Prononciation [soon-ah'-ee-ro]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>porter ensemble avec un autre ou d'autres</li>\n<li>amener ensemble avec d'autres\n<ol type=\"a\">\n<li>distribuer ou établir des comptes</li>\n<li>faire les comptes avec</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·αίρω</b>, <i>anc. att</i>. <b>ξυν·αίρω</b> <span>(<i>f</i>. -αρῶ, <i>ao</i>. συνῆρα, <i>etc</i>.)</span> lever ensemble <i>ou</i> avec, <i>particul. :</i><br><b>      1</b> lever <i>ou</i> prendre les armes en faveur de, secourir, <i>dat</i>. DC. <i>46, 3 ; Exc. 55, 66 ;</i><br><b>      2</b> σ. λόγον μετά τινος, NT. <i>Matth. 18, 23 ; 25, 19,</i> régler un compte avec qqn ;<br><b><i>Moy.</i></b> :<br><b>   I</b> lever ensemble pour soi : ὅπλα, DH. <i>7, 19,</i> prendre les armes avec d’autres ; <i>p. suite :</i><br><b>      1</b> se lever contre : τινι, PLUT. <i>Galb. 18, etc</i>. comme auxiliaire de qqn ; τινι ἔς τι, PAUS. <i>3, 1, 7,</i> comme auxiliaire de qqn pour qqe ch. ; ἐπί τινα, PLUT. <i>Dio. c. Brut. 3,</i> contre qqn ;<br><b>      2</b> venir au secours de, aider, assister : τινί τι, EUR. <i>Or. 767,</i> qqn en qqe ch. ; <i>abs</i>. DÉM. <i>1449, 16, etc. ;</i><br><b>      3</b> prendre sa part de, partager : τινι τὸν κίνδυνον, THC. <i>2, 71 ; ou</i> τοῦ κινδύνου, THC. <i>4, 10,</i> le danger de qqn ; τὰ πράγματα, DÉM. <i>16, 6,</i> mettre ensemble la main aux affaires ;<br><b>   II</b> soulever à la fois : τινα τῶν σκελῶν, PLUT. <i>Lys. 15,</i> qqn par les deux jambes, le culbuter.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συναιρω - συναίρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (3)</li>\n</ul>\n</td></tr>\n</table>","G4869":"<h1>sunaichmalotos</h1>\n<p>Strong n° 4869 <i>Prononciation [soon-aheekh-mal'-o-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un compagnon prisonnier</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συναιχμάλωτος, ος, ον</b> <span>[ᾰ]</span> compagnon de captivité, LUC. <i>As. 27 ;</i> NT. <i>Rom. 16, 7</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συναιχμαλωτος - συναιχμάλωτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Colossiens (1)</li>\n<li>Philémon (1)</li>\n</ul>\n</td></tr>\n</table>","G4870":"<h1>sunakoloutheo</h1>\n<p>Strong n° 4870 <i>Prononciation [soon-ak-ol-oo-theh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>suivre ensemble avec les autres, accompagner</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·ακολουθέω-ῶ</b> <span>[ᾰ]</span><br><b>   I</b> suivre ensemble, <i>càd. :</i><br><b>      1</b> suivre qqn plusieurs ensemble, THC. <i>2, 96 ;</i> XÉN. <i>An. 2, 5, 30, etc. ;</i><br><b>      2</b> suivre, aller de compagnie : τινι, THC. <i>6, 44 ;</i> XÉN. <i>Cyr. 3, 1, 43, etc. ;</i> AR. <i>Pl. 43 ;</i> μετά τινος, ISOCR. <i>71</i> b ; MÉN. <i>4, 184 Meineke ;</i> DS. <i>13, 62,</i> avec qqn ;<br><b>   II</b> <i>fig. :</i><br><b>      1</b> être <i>ou</i> tomber d’accord avec, <i>dat</i>. PLAT. <i>Leg. 711</i> c, <i>716</i> b ; ARSTT. <i>G.A. 2, 1, 14, etc. ;</i> τινί τι, PLAT. <i>Leg. 792</i> c, avec qqn en qqe ch., accorder qqe ch. à qqn ;<br><b>      2</b> être la conséquence commune de, se rattacher à la fois à, <i>gén</i>. ISOCR. <i>140 fin ;</i> μετά τινος, PLAT. <i>Rsp. 464</i> a, à qqe ch. ; <i>d’où en gén</i>. être la conséquence de, <i>dat</i>. PLAT. <i>Pol. 274</i> a ; <i>t. de log</i>. être la conséquence nécessaire de, ARSTT. <i>An. pr. 1, 46, 15, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνακολουτεω - συνακολουθέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4871":"<h1>sunalizo</h1>\n<p>Strong n° 4871 <i>Prononciation [soon-al-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>réunir ensemble, assembler</li>\n<li>manger avec (littéralement partager le sel avec)</li>\n<li>être assemblés, se rencontrer avec</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·αλίζω</b> <span>[ᾱ]</span> rassembler, réunir, HDT. <i>1, 125, etc. ;</i> XÉN. <i>Hell. 1, 1, 30 ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> se rassembler, HDT. <i>1, 62 ; 5, 15, etc. ; en parl. de choses,</i> HPC. <i>278, 55 ;</i> ARSTT. <i>G.A. 3, 11, 31 ;</i><br><b>      2</b> se réunir à d’autres, NT. <i>Ap. 1, 4 ;</i><br><b>      3</b> entrer dans une réunion, dans une classe, <i>avec</i> εἰς <i>et l’acc</i>. XÉN. <i>Cyr. 1, 2, 15</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συναλιζω - συναλίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4872":"<h1>sunanabaino</h1>\n<p>Strong n° 4872 <i>Prononciation [soon-an-ab-ah'-ee-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>monter au même moment, venir ensemble vers un lieu situé plus haut\n<ol type=\"a\">\n<li>avec quelqu'un</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·αναϐαίνω :<br>      1</b> monter ensemble <i>ou</i> en même temps : τινὶ ἅρμα, LUC. <i>Charid. 19,</i> monter avec qqn sur un char ;<br><b>      2</b> s’enfoncer de la côte dans l’intérieur d’un pays avec : τινί, XÉN. <i>An. 1, 3, 18 ;</i> ISOCR. <i>70</i> e, avec qqn ; <i>abs</i>. HDT. <i>7, 6 ;</i> XÉN. <i>An. 5, 4, 16 ;</i> ISOCR. <i>71</i> b, <i>etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συναναβαινω - συναναβαίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4873":"<h1>sunanakeimai</h1>\n<p>Strong n° 4873 <i>Prononciation [soon-an-ak'-i-mahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se reposer ensemble, faire la fête ou un festin ensemble\n<ol type=\"a\">\n<li>des hôtes, des convives</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·ανάκειμαι</b>, se mettre à table avec, <i>dat</i>. NT. <i>Matth. 9, 10, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνανακειμαι - συνανάκειμαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 9 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (4)</li>\n<li>Luc (3)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4874":"<h1>sunanamignumi</h1>\n<p>Strong n° 4874 <i>Prononciation [soon-an-am-ig'-noo-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mêler ensemble</li>\n<li>se tenir en compagnie avec, être intime avec quelqu'un, fréquenter</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·αναμίγνυμι</b>, <i>anc. att</i>. <b>ξυν·αναμίγνυμι</b>, mêler l’un avec l’autre, ATH. <i>177</i> b ; <i>au pass</i>. se mêler à, <i>dat</i>. PLUT. <i>Phil. 21, M. 256</i> a ; ATH. <i>256</i> a ; <i>fig</i>. devenir une partie de, <i>dat</i>. LUC. <i>Char. 15</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συναναμιγνυμι - συναναμίγνυμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (2)</li>\n<li>2 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G4875":"<h1>sunanapauomai</h1>\n<p>Strong n° 4875 <i>Prononciation [soon-an-ap-ow'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prendre du repos ensemble</li>\n<li>dormir ensemble, être couché avec\n<ol type=\"a\">\n<li>d'un mari et son épouse</li>\n<li>métaph. reposer ou rafraîchir son esprit avec quelqu'un (c.à.d. donner et recevoir un rafraîchissement par relation mutuelle)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·αναπαύομαι :<br>      1</b> se reposer <i>ou</i> dormir avec, <i>dat. en parl. de l’homme,</i> DH. <i>9, 4 ;</i> PLUT. <i>M. 125</i> a ; <i>en parl. de la femme,</i> PLUT. <i>M. 179</i> e ; <i>Rom. 5 ; en parl. d’animaux,</i> SPT. <i>Esaï. 11, 5 ;</i><br><b>      2</b> <i>fig</i>. être réconforté avec, <i>dat</i>. NT. <i>Rom. 15, 32</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao.2</i> συνανεπάην, HÉGÉSIPPE (EUS. <i>H.E. 4, 22</i>).</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συναναπαυομαι - συναναπαύομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4876":"<h1>sunantao</h1>\n<p>Strong n° 4876 <i>Prononciation [soon-an-tah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se rencontrer avec\n<ol type=\"a\">\n<li>d'événements : arriver ou se produire</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·αντάω-ῶ</b> <span>(<i>impf</i>. συνήντων, <i>f</i>. συναντήσω, <i>ao</i>. συνήντησα, <i>pf</i>. συνήντηκα)</span><br><b>   I. 1</b> se rencontrer avec, <i>dat</i>. EUR. <i>Ion 787 ;</i> AR. <i>Ach. 1187, Pl. 41, 44 ; postér. acc</i>. JAMBL. (PHOT. <i>Bibl. 76, 21, etc.) ; abs</i>. OD. <i>16, 333 ;</i> POL. <i>1, 52, 6, etc. ; d’où</i> se rassembler, <i>avec</i> εἰς <i>et l’acc</i>. PHILIPP. (DÉM. <i>280, 10</i>) ;<br><b>      2</b> <i>avec idée d’hostilité,</i> se rencontrer, en venir aux mains, POL. <i>3, 92, 9 ;</i><br><b>      3</b> se rencontrer, survenir, arriver, PLUT. <i>Syll. 2 ;</i> DL. <i>6, 38 ;</i> NT. <i>Ap. 20, 22 ;</i><br><b>   II</b> <b><i>Moy.</i></b> <span>(<i>ao</i>. συνηντησάμην, <i>pf</i>. συνήντημαι)</span><br><b>      1</b> se rencontrer avec, <i>dat</i>. IL. <i>17, 134 ;</i><br><b>      2</b> <i>en parl. de choses,</i> se rencontrer, survenir, POL. <i>22, 7, 14</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. 3 duel épq</i>. συναντήτην, OD. <i>l. c. ; impf. ion</i>. συνήντεον, A. RH. <i>4, 1486 ;</i> NONN. <i>Jo. 11, 72</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνανταω - συναντάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Actes (2)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G4877":"<h1>sunantesis</h1>\n<p>Strong n° 4877 <i>Prononciation [soon-an'-tay-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une rencontre avec</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συνάντησις, εως (ἡ)</b> rencontre, HPC. <i>15, 8 ;</i> EUR. <i>Ion 535 ;</i> PLUT. <i>Pyrrh. 16 ; au plur</i>. DH. <i>4, 66</i>.<br><span><b>Étym</b>. συναντάω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συναντησις - συνάντησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G4878":"<h1>sunantilambanomai</h1>\n<p>Strong n° 4878 <i>Prononciation [soon-an-tee-lam-ban'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se tenir tout-au-long avec, s'efforcer d'obtenir avec les autres, aider dans l'obtention</li>\n<li>saisir avec un autre</li>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·αντιλαμϐάνομαι :<br>      1</b> aider à se rendre maître de, <i>gén</i>. DS. <i>14, 8 ;</i><br><b>      2</b> aider à supporter, <i>acc</i>. SPT. <i>Num. 11, 17 ;</i><br><b>      3</b> prendre le parti de, venir au secours de, <i>dat</i>. SPT. <i>Ex. 18, 22 ; Ps. 88, 21</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συναντιλαμβανομαι - συναντιλαμβάνομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4879":"<h1>sunapago</h1>\n<p>Strong n° 4879 <i>Prononciation [soon-ap-ag'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>conduire au loin avec ou ensemble</li>\n<li>métaph. être entraîné avec\n<ol type=\"a\">\n<li>d'une chose, c.à.d. par une chose, comme pour éprouver avec les autres la force de ce qui nous entraîne</li>\n<li>céder ou de soumettre aux choses, conditions, emplois les plus humbles : ne pas éluder leur pouvoir</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·απάγω</b> <span>[ᾰᾰ]</span><br><b>      1</b> emmener <i>ou</i> détourner avec, <i>dat</i>. XÉN. <i>Cyr. 8, 3, 23, etc. ; abs</i>. XÉN. <i>Hell. 5, 1, 23 ; au pass</i>. se laisser détourner avec, NT. <i>Gal. 2, 13 ; 2Petr. 3, 17 ;</i><br><b>      2</b> <i>au pass. : c</i>. συμπεριφέρομαι, NT. <i>Rom. 12, 16</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συναπαγω - συναπάγω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Galates (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4880":"<h1>sunapothnesko</h1>\n<p>Strong n° 4880 <i>Prononciation [soon-ap-oth-nace'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mourir ensemble</li>\n<li>mourir avec quelqu'un</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·αποθνῄσκω</b>, mourir avec, <i>dat</i>. HDT. <i>3, 16 ; 5, 47 ; 7, 222 ; abs</i>. PLAT. <i>Phæd. 88</i> d ; <i>fig. en parl. de choses (maladie, désir, etc</i>.) HPC. <i>Aph. 1246 ;</i> GORG. <i>5, 550 Walz ;</i> ISOCR. <i>425</i> c ; ARSTT. <i>H.A. 10, 7, 3 ; G.A. 4, 7, 3 ;</i> DS. <i>15, 79</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συναποθνησκω - συναποθνῄσκω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4881":"<h1>sunapollumi</h1>\n<p>Strong n° 4881 <i>Prononciation [soon-ap-ol'-loo-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>détruire ensemble</li>\n<li>périr ensemble (être tué avec)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·απόλλυμι</b>, <i>anc. att</i>. <b>ξυν·απόλλυμι</b> <span>(<i>ao</i>. συναπώλεσα)</span> perdre, faire périr <i>ou</i> détruire avec soi : τινά, THC. <i>6, 12 ;</i> HYPÉR. <i>Lyc. 15,</i> qqn ; τι, DÉM. <i>907, 14,</i> qqe ch. ; τινί τι, PLUT. <i>Cato mi. 38,</i> une chose avec une autre ; σ. μετά τινος, ANT. <i>139, 7,</i> perdre avec qqn ;<br><b><i>Moy.</i></b> <span>(<i>ao.2</i> συναπωλόμην)</span> être perdu <i>ou</i> périr avec, <i>dat</i>. HDT. <i>7, 221 ;</i> PLAT. <i>Criti. 121</i> a ; <i>abs</i>. THC. <i>2, 60 ;</i> LYS. <i>128, 20 ;</i> PLUT. <i>Syll. 29, Luc. 29, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συναπολλυμι - συναπόλλυμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4882":"<h1>sunapostello</h1>\n<p>Strong n° 4882 <i>Prononciation [soon-ap-os-tel'-lo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>envoyer avec</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·αποστέλλω</b>, envoyer ensemble <i>ou</i> en même temps, THC. <i>6, 88 ;</i> XÉN. <i>Cyr. 3, 3, 4 ; 5, 2, 37 ;</i> IS. <i>59, 9, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συναποστελλω - συναποστέλλω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4883":"<h1>sunarmologeo</h1>\n<p>Strong n° 4883 <i>Prononciation [soon-ar-mol-og-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>joindre étroitement ensemble</li>\n<li>structurer ensemble\n<ol type=\"a\">\n<li>les parties d'un immeuble</li>\n<li>les membres du corps</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·αρμολογέω-ῶ</b>, <i>c</i>. συναρμόζω NT. <i>Eph. 2, 21 ; 4, 16</i>.<br><br>\n<b>συν·αρμόζω</b>, <i>anc. att</i>. <b>ξυν·αρμόζω :<br>   I <i>tr</i>.<br>      1</b> ajuster ensemble, joindre ensemble, réunir en adaptant : σ. βλέφαρα χειρί, EUR. <i>Ph. 1451,</i> fermer avec la main les yeux (d’un mourant) ; σ. τι πρός τι, ARSTT. <i>H.A. 5, 6, 1,</i> ajuster une chose avec une autre ; <i>au pass</i>. être ajusté, PLAT. <i>Rsp. 411</i> e ; λίθοι εὖ συνηρμοσμένοι, HDT. <i>1, 163,</i> pierres bien ajustées ;<br><b>      2</b> <i>p. suite,</i> ajuster les parties d’un tout, <i>d’où</i> ajuster, édifier, charpenter : σκάφος, EUR. <i>Hel. 233,</i> une barque ; ἵππον, EUR. <i>Tr. 11,</i> un cheval (de bois) ; σῶμα, XÉN. <i>Mem. 1, 4, 8,</i> le corps ; <i>fig</i>. σ. πόλιν, PLAT. <i>Leg. 628</i> a, ordonner, bien organiser un État ; τὰ τῆς ἀρχῆς οὐ συναρμοσμένα καλῶς, DÉM. <i>154, 16,</i> souveraineté sans véritable consistance ni cohésion ; σ. περιόδους, DH. <i>Comp. 9,</i> ajuster, construire des périodes ; σ. τοὺς πολίτας, PLAT. <i>Leg. 519</i> e, unir les citoyens ; φιλίᾳ συνηρμόσθαι, LYS. <i>fr. 60 Bkk</i>. être lié d’amitié ; <i>avec une prép. :</i> σ. σῶμα ἐκ τοιούτων, XÉN. <i>Cyn. 5, 31,</i> former le corps de tels éléments ; σ. τοὔνομα (θάλλειν) ἀπὸ τοῦ θεῖν καὶ ἅλλεσθαι, PLAT. <i>Crat. 414</i> b, former le mot θάλλειν par la combinaison <i>de</i> θεῖν (courir) et de ἅλλεσθαι (sauter) ;<br><b>      3</b> <i>en gén</i>. adapter, ajuster : συνηρμοσμένη λύρα πρὸς τὸν αὐλόν, XÉN. <i>Conv. 3, 1,</i> lyre accordée avec la flûte ; <i>d’ordin. avec le dat. :</i> σ. χείλεα στομάτεσσιν, ANTH. <i>9, 362, 9,</i> appliquer les lèvres sur la bouche ; μέρη ξυναρμοσθέντα αὐτὰ αὑτοῖς, PLAT. <i>Tim. 56</i> c, parties ajustées les unes avec les autres ; σ. βροτοὺς εὐχερείᾳ, ESCHL. <i>Eum. 494,</i> accoutumer les hommes à prendre facilement leur parti (du crime), les rendre indifférents au crime ;<br><b>   II <i>intr.</i></b> convenir à, s’accorder avec, s’harmoniser avec, <i>dat</i>. XÉN. <i>Cyr. 8, 4, 19 ; Mem. 2, 6, 24, 25 ;</i> PLAT. <i>Prot. 333</i> a ; τινὶ σ. εἰς φιλίαν, XÉN. <i>Mem. 2, 6, 20,</i> se lier d’amitié avec qqn ; <i>avec</i> εἰς <i>et l’acc</i>. PLAT. <i>Leg. 729</i> a ; ARSTT. <i>Metaph. 1, 5 ;</i><br><b><i>Moy.</i></b> :<br><b>      1 <i>tr.</i></b> arranger, concilier, unir pour soi, PLAT. <i>Tim. 53</i> e, <i>Pol. 309</i> c, <i>etc. ;</i> PLUT. <i>Sol. 15 ;</i><br><b>      2 <i>intr.</i></b> s’accorder avec : καιρῷ, DL. <i>4, 37 ;</i> πρὸς τὰ παρόντα, XÉN. <i>Ap. 16,</i> s’accommoder aux circonstances.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συναρμολογεω - συναρμολογέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4884":"<h1>sunarpazo</h1>\n<p>Strong n° 4884 <i>Prononciation [soon-ar-pad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>saisir de force</li>\n<li>attraper ou s'emparer de quelqu'un (qui n'est plus son propre maître)</li>\n<li>saisir par la force et entraîner au loin</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·αρπάζω</b>, <i>anc. att</i>. <b>ξυν·αρπάζω :<br>   I</b> <i>au propre :</i><br><b>      1</b> se saisir plusieurs ensemble de, <i>acc</i>. LYS. <i>100, 28, etc. ; au pass</i>. SOPH. <i>Aj. 498, fr. 587 Dind., etc. ;</i><br><b>      2</b> se saisir de plusieurs personnes <i>ou</i> de plusieurs choses ensemble, ESCHL. <i>Pers. 195 ;</i> SOPH. <i>El. 1150 ;</i> enlever tout à la fois, XÉN. <i>Cyr. 4, 2, 26, etc. ;</i><br><b>      3</b> saisir pour réunir, <i>acc</i>. EUR. <i>Hec. 1163 ; cf</i>. LYS. <i>fr. 45, 4 ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> captiver, EUR. <i>I.A. 531 ;</i> CALL. <i>Epigr. 31, 5 ;</i> ANTH. <i>5, 210 ;</i> LGN <i>16, 2, etc. ;</i><br><b>      2</b> saisir vivement par l’esprit, SOPH. <i>Aj. 16 ;</i> AR. <i>Nub. 775 ;</i> SIMYL. (STOB. <i>Fl. 60, 4) ; particul</i>. dans un raisonnement : σ. τὸ ζητούμενον, SEXT. <i>P. 2, 35 ;</i> LUC. <i>J. tr. 38,</i> s’emparer de la conclusion même que l’on cherche, <i>càd</i>. faire une pétition de principe ;<br><b><i>Moy.</i></b> se saisir de, <i>acc</i>. AR. <i>Lys. 437</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συναρπαζω - συναρπάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G4885":"<h1>sunauxano</h1>\n<p>Strong n° 4885 <i>Prononciation [soon-owx-an'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire croître ensemble</li>\n<li>pousser ensemble</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·αυξάνω</b>, accroître avec <i>ou</i> en même temps, XÉN. <i>Cyr. 8, 3, 21 ;</i> POL. <i>6, 15, 7 ;</i> PLUT. <i>Sert. 9 ; au pass</i>. s’accroître ensemble, s’accroître, grandir avec, <i>dat</i>. XÉN. <i>Cyr. 8, 7, 6 ;</i> ISOCR. <i>193</i> c ; DÉM. <i>107, 27</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συναυξανω - συναυξάνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G4886":"<h1>sundesmos</h1>\n<p>Strong n° 4886 Prononciation [soon'-des-mos]</p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce qui relie ensemble, une bande, un lien\n<ol type=\"a\">\n<li>des ligaments par lesquels sont réunis les membres du corps</li>\n</ol>\n</li>\n<li>ce qui est relié ensemble, un paquet</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σύνδεσμος</b>, <i>anc. att</i>. <b>ξύνδεσμος, ου (ὁ)</b> <i>plur</i>. σύνδεσμα, <b>ων (τὰ) :<br>   I</b> action de lier ensemble, union, PLAT. <i>Epin. 984 c. ;</i> ARSTT. <i>An. post. 2, 10, 1, etc. ;</i><br><b>   II</b> lien, THC. <i>2, 75 ;</i> EUR. <i>Med. 1193, etc. ; fig</i>. lien d’amitié, de concorde, <i>etc</i>. PLAT. <i>Rsp. 520</i> a, <i>Pol. 310</i> a, <i>Leg. 921</i> c, <i>etc. ;</i> ARSTT. <i>Nic. 8, 12, 7, etc. ; en mauv. part,</i> conspiration, SPT. <i>4Reg. 11, 14 ; Jer. 11, 9 ; particul. :</i><br><b>      1</b> liens du corps, assemblage <i>ou</i> consistance des parties du corps, EUR. <i>Hipp. 199 ;</i> T. LOCR. <i>100</i> b ; ARSTT. <i>P.A. 2, 6, 7, etc. ;</i><br><b>      2</b> <i>t. de gr</i>. particule, <i>d’ord</i>. conjonction, ISOCR. <i>fr. 2, 4 Bensel. ;</i> ARSTT. <i>Rhet. 3, 5, 2, etc. ; qqf</i>. préposition, DH. <i>Comp. 22, p. 310 Schæf. ;</i> DL. <i>7, 71 et 72 ;</i><br><b>      3</b> <i>t. de math</i>. point de rencontre <i>ou</i> intersection de deux lignes, conjonction de deux astres, CLÉOM. <i>Cycl. theor. 2, 5, p. 138 ;</i> MAN. <i>2, 498, etc. ;</i><br><b>   III</b> faisceau, paquet, HDN <i>4, 12</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Plur. hétérog</i>. τὰ σύνδεσμα, EUR. <i>l. c. etc</i>.<br><span><b>Étym</b>. συνδέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνδεσμος - σύνδεσμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4887":"<h1>sundeo</h1>\n<p>Strong n° 4887 <i>Prononciation [soon-deh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>attacher ensemble, lier ensemble</li>\n<li>lier ou attacher de tous côtés</li>\n<li>lier conjointement avec un autre, des prisonniers</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·δέω</b>, <i>ion. et anc. att</i>. <b>ξυν·δέω</b> <span>(<i>f</i>. δήσω, <i>ao</i>. συνέδησα, <i>pf</i>. συνδέδεκα, <i>etc</i>.)</span><br><b>      1</b> lier ensemble : πόδας, OD. <i>10, 168,</i> les pieds ; τοὺς πόδας καὶ τὰς χεῖρας, PLAT. <i>Euthyphr. 4</i> c, lier les pieds et les mains ; <i>cf</i>. IL. <i>1, 399 ;</i> HDT. <i>9, 119 ;</i> SOPH. <i>Ph. 1016, etc. ; fig</i>. lier, unir étroitement : σ. τὴν ψυχήν, PLAT. <i>Tim. 84</i> a, unir l’âme au corps ; <i>cf</i>. PLAT. <i>Tim. 73</i> b, <i>Conv. 202</i> e, <i>etc. ;</i> σ. τι ἀπό τινος, LUC. <i>Syr. 29,</i> lier une chose à une autre ; φίλους φίλοις πόλεις τε πόλεσι ξ. EUR. <i>Ph. 538,</i> lier les amis aux amis et les cités aux cités ; ξ. τὰς πόλεις, PLAT. <i>Leg. 875</i> a, unir les cités ; <i>abs</i>. lier, unir (par amitié) PLAT. <i>Rsp. 462</i> b ; <i>joint à</i> συνέχειν, PLAT. <i>Phæd. 99</i> c ;<br><b>      2</b> former de parties liées entre elles ; καλιήν, LUC. <i>Syr. 29,</i> construire un nid solide ;<br><b><i>Moy.</i></b> :<br><b>      1 <i>tr.</i></b> lier, unir, T. LOCR. <i>99</i> a ;<br><b>      2 <i>intr.</i></b> s’unir, former une union, PLAT. <i>Pol. 310</i> b ; THÉM. <i>59</i> a.<br><span><b><span class=\"arrow\"></span></b> <i>La contraction se fait dans les formes en</i> -εε- <i>ou</i> -εει- <i>et peut se faire dans les formes en</i> -εόμενος, η, ον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνδεω - συνδέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4888":"<h1>sundoxazo</h1>\n<p>Strong n° 4888 <i>Prononciation [soon-dox-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>approuver ensemble, se joindre dans l'approbation</li>\n<li>glorifier ensemble</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·δοξάζω :<br>      1</b> approuver ensemble, ARSTT. <i>Pol. 5, 9, 12 ;</i><br><b>      2</b> convenir de, consentir à, PORPH. (STOB. <i>Fl. 1, 88</i>) ;<br><b>      3</b> glorifier ensemble, <i>au pass</i>. NT. <i>Rom. 8, 17</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνδοξαζω - συνδοξάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4889":"<h1>sundoulos</h1>\n<p>Strong n° 4889 <i>Prononciation [soon'-doo-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un compagnon de service, quelqu'un qui sert le même maître avec un autre\n<ol type=\"a\">\n<li>l'associé d'un serviteur (ou esclave)</li>\n<li>quelqu'un qui sert un roi avec d'autres</li>\n<li>collègue de quelqu'un qui est serviteur de Christ dans la publication de l'évangile</li>\n<li>quelqu'un qui avec d'autres connaît le même Seigneur, Jésus, et obéit à ses commandements</li>\n<li>quelqu'un qui avec d'autres est sujet à la même autorité divine dans le gouvernement Messianique\n<ol>\n<li>des anges, qui sont les compagnons de service des Chrétiens</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σύνδουλος, ου (ὁ, ἡ)</b> compagnon d’esclavage, <i>au masc</i>. EUR. <i>Ion 1109 ;</i> AR. <i>Pax 745, etc. ; au fém</i>. HDT. <i>1, 110 ; 2, 134 ;</i> EUR. <i>Med. 65, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. συνδούλη, BABR. <i>f. 3, 6</i>.<br><span><b>Étym</b>. σ. δοῦλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνδουλος - σύνδουλος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Colossiens (2)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G4890":"<h1>sundrome</h1>\n<p>Strong n° 4890 <i>Prononciation [soon-drom-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>courir ensemble, concours, affluence spéc. hostile ou tapageuse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συνδρομή, ῆς (ἡ) :<br>   I</b> concours, <i>càd. :</i><br><b>      1</b> action de se réunir tumultueusement, <i>d’où</i> réunion tumultueuse, CÉPHISOD. (ARSTT. <i>Rhet. 3, 10, 7</i>) ; DS. <i>3, 71 ; 15, 90 ;</i> POSIDON. (ATH. <i>212</i> e) ; ἀπὸ συνδρομῆς, DS. <i>13, 87,</i> tumultueusement ;<br><b>      2</b> affluence de choses, de biens, STR. <i>235 ;</i> σ. αἵματος εἰς τόπον, ARSTT. <i>Probl. 9, 3,</i> afflux de sang sur une partie du corps ;<br><b>      3</b> le fait de se rencontrer <i>ou</i> d’aboutir, <i>d’où</i> conclusion d’un discours, morale d’un récit, ANTH. <i>9, 203 ;</i><br><b>   II</b> <i>t. de rhét</i>. concession, RHÉT. <i>3, 296 W. ; 9, 383 W</i>.<br><span><b>Étym</b>. συνδραμεῖν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνδρομη - συνδρομή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4891":"<h1>sunegeiro</h1>\n<p>Strong n° 4891 <i>Prononciation [soon-eg-i'-ro]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se lever ensemble, faire lever avec</li>\n<li>ressusciter ensemble de la mort pour une vie nouvelle et bénie vouée à Dieu</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·εγείρω</b>, éveiller <i>ou</i> raviver en même temps, PHOCYL. <i>fr. 140 Bgk ;</i> NT. <i>Eph. 2, 6 ; fig</i>. PLUT. <i>M. 117</i> c ; <i>au pass</i>. SPT. <i>Esaï. 14, 9 ;</i> NT. <i>Col. 2, 12 ; 3, 1</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνεγειρω - συνεγείρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>Colossiens (3)</li>\n</ul>\n</td></tr>\n</table>","G4892":"<h1>sunedrion</h1>\n<p>Strong n° 4892 <i>Prononciation [soon-ed'-ree-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>sanhédrin = « conseil, tribunal »\n<ol>\n<li>toute assemblée (spéc. de magistrats, juges, ambassadeurs), réunie pour délibérer ou juger</li>\n<li>toute session d'assemblée du peuple réunie pour délibération\n<ol type=\"a\">\n<li>le Sanhédrin, le grand conseil de Jérusalem, était composé de soixante et onze membres, scribes, anciens, membres de familles sacrificateurs, et d'un souverain sacrificateur, président de l'assemblée. Les cas importants étaient amenés à cette assemblée, dans la mesure où la réglementation Romaine lui en avait laissé le pouvoir, et il pouvait s'y prononcer la peine de mort, à condition que cette sentence soit confirmée par le procurateur Romain.</li>\n<li>un plus petit tribunal ou conseil qui se tenait dans chaque ville Juive, pour les décisions ou cas moins importants</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συνέδριον, ου (τὸ) :<br>   I</b> assemblée siégeant, XÉN. <i>Hell. 1, 1, 31 ;</i> PLAT. <i>Prot. 317</i> d, <i>etc. ; particul. :</i><br><b>      1</b> conseil des amphictions, XÉN. <i>Hell. 7, 1, 39 ;</i> DÉM. <i>232, 19, etc. ;</i><br><b>      2</b> assemblée générale <i>ou</i> congrès des Grecs après les guerres Médiques, DS. <i>11, 70 ; 15, 28 ;</i><br><b>      3</b> collège <i>ou</i> compagnie judiciaire, <i>en parl. de l’Aréopage,</i> DÉM. <i>1373, 12 et 22 ;</i> ESCHN. <i>13, 11 ;</i> DIN. <i>97, 9, etc. ;</i><br><b>      4</b> le Sénat, <i>à Rome,</i> POL. <i>1, 11, 1, etc. ; à Carthage,</i> POL. <i>1, 11, 1 ; 1, 31, 8, etc</i>. DC. <i>37, 26 ;</i><br><b>      5</b> <i>chez les Juifs,</i> le sanhédrin, NT. <i>Matth. 5, 22, etc. ;</i><br><b>      6</b> conseil de guerre, HDT. <i>8, 56, 75, etc. ;</i><br><b>   II</b> lieu des séances d’une assemblée, HDT. <i>8, 79 ;</i> XÉN. <i>Hell. 2, 4, 23 ;</i> LYS. <i>144, 39, etc</i>.<br><span><b>Étym</b>. σύνεδρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνεδριον - συνέδριον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n22 fois dans 22 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (3)</li>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Actes (14)</li>\n</ul>\n</td></tr>\n</table>","G4893":"<h1>suneidesis</h1>\n<p>Strong n° 4893 <i>Prononciation [soon-i'-day-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la conscience de toute chose</li>\n<li>l'âme qui distingue entre ce qui est moralement bon ou mauvais, prompte à faire le mal, fuyant le bon, commandant l'un, condamnant l'autre\n<ol type=\"a\">\n<li>la conscience</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συνείδησις, εως (ἡ) :<br>      1</b> sentiment intime, conscience (de ses propres pensées, de ses propres actes) NT. <i>2Cor. 4, 2 ; 5, 11, etc. ;</i> DS. <i>4, 6 ;</i> LUC. <i>Am. 49 ;</i><br><b>      2</b> <i>au sens mor</i>. conscience du bien et du mal, DH. <i>Thuc. 8 ;</i> SPT. <i>Sap. 17, 11 ;</i> NT. <i>Ap. 23, 1, etc. ; 1Tim. 3, 9</i>.<br><span><b>Étym</b>. σύνοιδα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνειδησις - συνείδησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n32 fois dans 30 versets de 10 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Actes (2)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (9)</li>\n<li>2 Corinthiens (3)</li>\n<li>1 Timothée (4)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (5)</li>\n<li>1 Pierre (3)</li>\n</ul>\n</td></tr>\n</table>","G4894":"<h1>suneido</h1>\n<p>Strong n° 4894 <i>Prononciation [soon-i'-do]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>voir (avoir vu) ensemble avec les autres</li>\n<li>voir (avoir vu) dans son esprit, en soi-même\n<ol type=\"a\">\n<li>comprendre, percevoir</li>\n</ol>\n</li>\n<li>connaître avec un autre</li>\n<li>connaître dans son esprit, avoir conscience de</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·οράω</b> <span>(<i>f</i>. συνόψομαι, <i>ao.2</i> συνεῖδον, <i>etc</i>.)</span><br><b>      1</b> voir ensemble, embrasser d’un coup d’œil, <i>acc</i>. PLAT. <i>Leg. 904</i> b, <i>etc. ; avec</i> ὅτι, ISOCR. <i>93</i> d ; <i>avec</i> ὡς, LUC. <i>J. tr. 42 ; avec</i> εἰ, ISOCR. <i>16</i> b ; <i>avec un relat</i>. (ποία, ARSTT. <i>Nic. 10, 9, 23 ;</i> πότερον, ARSTT. <i>Phys. 7, 1, 1, etc.) ; avec un part. :</i> συνιδεῖν ἦν ἡ ἀρχὴ ἰσχυρὰ οὖσα, XÉN. <i>An. 1, 5, 9,</i> on pouvait voir, en y faisant attention, que l’empire du roi était puissant ;<br><b>      2</b> se voir les uns les autres : πυρὰ ἔκαιον καὶ συνεώρων ἀλλήλους, XÉN. <i>An. 4, 1, 11,</i> ils allumaient des feux et se faisaient des signaux les uns aux autres.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνειδω - συνοράω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (3)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4895":"<h1>suneimi</h1>\n<p>Strong n° 4895 <i>Prononciation [soon'-i-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être avec</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σύν·ειμι</b>, <i>anc. att</i>. <b>ξύν·ειμι</b> <span>(<i>inf</i>. συνεῖναι, <i>f</i>. συνέσομαι)</span><br><b>   I</b> être avec, se trouver avec, <i>dat</i>. SOPH. <i>Ant. 372, O.C. 946 ;</i> ἐμοὶ γὰρ οὐδὲ ξύνεστιν ἐλπίς, EUR. <i>Tr. 677,</i> car il n’y a plus même d’espérance en moi ;<br><b>   II</b> être ordinairement avec, <i>càd. :</i><br><b>      1</b> avoir des relations habituelles avec, fréquenter : τινι, XÉN. <i>Mem. 2, 1, 32 ;</i> PLAT. <i>Conv. 176</i> e, <i>Prot. 347</i> c ; EUR. <i>Hipp. 948 ;</i> μετά τινος, PLAT. <i>Conv. 195</i> b, <i>etc</i>. qqn ; <i>abs</i>. SOPH. <i>El. 1359 ;</i> AR. <i>Vesp. 236 ; particul</i>. avoir des relations de disciple à maître, XÉN. <i>Mem. 1, 2, 24,</i> PLAT. <i>1 Alc. 118</i> c ; de maître à disciple, XÉN. <i>Cyr. 3, 3, 14 ; Conv. 4, 4 ;</i> LUC. <i>J. tr. 27 ; subst</i>. οἱ συνόντες, les hôtes, AR. <i>Vesp. 1300 ;</i> XÉN. <i>Conv. 1, 15, etc. ;</i> les compagnons, les amis <i>ou</i> les disciples, PLAT. <i>Ap. 25</i> e, <i>Theæt. 168</i> a, <i>etc. ; particul</i>. les compagnons d’armes, XÉN. <i>Cyr. 8, 2, 2 ; Ages. 5, 2 ;</i><br><b>      2</b> s’unir à, <i>dat. ; particul</i>. avoir des relations avec un homme, HDT. <i>4, 9 ;</i> SOPH. <i>El. 276, 562 ;</i> avec une femme, EUR. <i>Hel. 297 ;</i> AR. <i>Eccl. 340, etc. ; en parl. d’animaux,</i> s’accoupler, ARSTT. <i>H.A. 5, 2 ;</i><br><b>      3</b> s’adonner à : πράγμασι, AR. <i>Ran. 959,</i> aux affaires ; γεωργίᾳ, XÉN. <i>Œc. 15, 12,</i> à l’agriculture ; ἡδοναῖς, PLAT. <i>Rsp. 586</i> a, aux plaisirs ; <i>d’où</i> être livré à, en proie à : ὀϊζυῖ, OD. <i>7, 270,</i> au malheur ; νόσῳ, SOPH. <i>O.R. 303,</i> à la maladie ; ὀνείρασιν, ESCHL. <i>Pers. 177,</i> être hanté par des songes ; <i>avec un n. de ch. pour suj</i>. être attaché à qqn, <i>en parl. du malheur,</i> SOPH. <i>O.C. 1244 ; de la maladie,</i> SOPH. <i>Aj. 338 ;</i> ὁ χρόνος ξυνὼν μακρός, SOPH. <i>O.C. 7,</i> le long temps qui a commencé avec moi (<i>litt</i>. né avec moi, existant avec moi), <i>càd</i>. la vieillesse ; <i>cf</i>. SOPH. <i>O.R. 1082 ;</i><br><b>   III</b> venir au secours de, assister, <i>dat</i>. ESCHL. <i>Sept. 671 ;</i> SOPH. <i>Aj. 700, O.R. 275, 863, etc. ;</i> EUR. <i>Hec. 879 ; particul</i>. assister de ses conseils, <i>dat</i>. THC. <i>4, 83 ;</i><br><b>   IV</b> se rencontrer, être en conjonction, <i>en parl. d’astres,</i> MAN. <i>1, 78, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνειμι - σύνειμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4896":"<h1>suneimi</h1>\n<p>Strong n° 4896 <i>Prononciation [soon'-i-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>venir ensemble</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σύν·ειμι</b>, <i>ion. et anc. att</i>. <b>ξύν·ειμι</b> <span>(<i>inf</i>. συνιέναι)</span> aller <i>ou</i> venir ensemble :<br><b>   I</b> <i>au propre, càd. :</i><br><b>      1</b> se rassembler, se réunir, IL. <i>4, 446 ; 8, 60 ;</i> HDT. <i>1, 62 ;</i> THC. <i>2, 10 ; particul. en parl. d’assemblées,</i> se rassembler pour délibérer, THC. <i>2, 15 ;</i> ARSTT. <i>Pol. 4, 14, 4 ; en parl. de conspiration,</i> DÉM. <i>745, 15 ; en parl. de l’assemblée elle-même,</i> PLAT. <i>Leg. 962</i> c ; <i>avec un rég. de m. sign. :</i> ξ. ξυνόδους, PLAT. <i>Conv. 197</i> d, tenir des réunions ;<br><b>      2</b> s’unir par mariage, PLAT. <i>Leg. 773</i> a ; <i>en parl. de relations sexuelles,</i> DS. <i>17, 77 ; en parl. d’animaux,</i> s’accoupler, ARSTT. <i>H.A. 5, 2, 2 ;</i><br><b>      3</b> se réunir pour en venir aux mains, IL. <i>6, 120, etc. ; d’où</i> en venir aux mains, IL. <i>14, 393 ; 20, 66, etc. ;</i> HÉS. <i>Th. 705 ;</i> HDT. <i>1, 80 ; en parl. d’États,</i> engager une guerre, THC. <i>2, 8 ;</i><br><b>      4</b> <i>en parl. de choses,</i> se réunir, se condenser, <i>en parl. de l’air,</i> PLAT. <i>Tim. 49</i> c ; <i>de l’humidité,</i> TH. <i>C.P. 2, 19, 3, etc. ;</i><br><b>      5</b> se resserrer, se contracter, ARSTT. <i>Meteor. 1, 4, 12, etc. ;</i><br><b>      6</b> entrer en conjonction, <i>en parl. d’astres,</i> MAN. <i>2, 423, etc. ;</i><br><b>      7</b> se réunir, s’amasser, <i>en parl. de revenus,</i> HDT. <i>1, 64 ; 4, 1</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνειμι - σύνειμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4897":"<h1>suneiserchomai</h1>\n<p>Strong n° 4897 <i>Prononciation [soon-ice-er'-khom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>entrer ensemble</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·εισέρχομαι</b>, entrer ensemble dans, <i>acc</i>. EUR. <i>Hel. 327, ou avec</i> ἐς <i>et l’acc</i>. THC. <i>4, 57 ;</i> EUR. <i>Hel. 1083</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνεισερχομαι - συνεισέρχομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Jean (3)</li>\n</ul>\n</td></tr>\n</table>","G4898":"<h1>sunekdemos</h1>\n<p>Strong n° 4898 <i>Prononciation [soon-ek'-day-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un compagnon de voyage</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·έκδημος, ος, ον</b>, qui voyage à l’étranger avec, compagnon de voyage, PLUT. <i>Oth. 5 ;</i> NT. <i>Ap. 19, 29</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνεκδημος - συνέκδημος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4899":"<h1>suneklektos</h1>\n<p>Strong n° 4899 <i>Prononciation [soon-ek-lek-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>élus ou choisis ensemble (par Dieu pour la vie éternelle)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συν·εκλεκτός, ή, όν</b>, choisi <i>ou</i> élu avec, NT. <i>1Petr. 5, 13</i>.<br><span><b>Étym</b>. σύν, ἐκλέγω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συνεκλεκτος - συνεκλεκτός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>"};
